UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Class Selector Values - CS7</div><p>Class Selector values keep backward compatibility with IP (Internet Protocol) Precedence: CSx has DSCP (Differentiated Services Code Point) value 8x. CS0=0, CS1=8, CS2=16, CS3=24, CS4=32, CS5=40, CS6=48, CS7=56.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>56</strong>: CS7 is DSCP 56.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>48</strong>: DSCP 48 is the value for CS6, not for CS7.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>40</strong>: DSCP 40 is the value for CS5, not for CS7.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>32</strong>: DSCP 32 is the value for CS4, not for CS7.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the formula:</p><ul><li>CSx = 8x.</li><li>AFxy = 8x + 2y.</li><li>EF = 46.</li><li>DF = 0.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📋 IPv4 Header - Full Reference (Memorize This):</div><table style=\"width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;\"><tr><td colspan=\"4\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Version<br><span style=\"font-size:12px;\">4 bits</span></td><td colspan=\"4\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">IHL<br><span style=\"font-size:12px;\">4 bits</span></td><td colspan=\"6\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">DSCP<br><span style=\"font-size:12px;\">6 bits</span></td><td colspan=\"2\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">ECN<br><span style=\"font-size:12px;\">2 bits</span></td><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Total Length<br><span style=\"font-size:12px;\">16 bits</span></td></tr><tr><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Identification<br><span style=\"font-size:12px;\">16 bits</span></td><td colspan=\"3\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Flags<br><span style=\"font-size:12px;\">3 bits</span></td><td colspan=\"13\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Fragment Offset<br><span style=\"font-size:12px;\">13 bits</span></td></tr><tr><td colspan=\"8\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">TTL<br><span style=\"font-size:12px;\">8 bits</span></td><td colspan=\"8\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Protocol<br><span style=\"font-size:12px;\">8 bits</span></td><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Header Checksum<br><span style=\"font-size:12px;\">16 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Source Address<br><span style=\"font-size:12px;\">32 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Destination Address<br><span style=\"font-size:12px;\">32 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Options + Padding<br><span style=\"font-size:12px;\">0-40 bytes</span></td></tr></table><div style=\"font-size:14px;line-height:1.7;margin-top:10px;\"><div style=\"margin-bottom:7px;\"><strong>Version</strong> <span style=\"opacity:0.75;\">(4 bits)</span>: IP version (4)</div><div style=\"margin-bottom:7px;\"><strong>IHL (Internet Header Length)</strong> <span style=\"opacity:0.75;\">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style=\"margin-bottom:7px;\"><strong>DSCP (Differentiated Services Code Point)</strong> <span style=\"opacity:0.75;\">(6 bits)</span>: QoS marking (0-63)</div><div style=\"margin-bottom:7px;\"><strong>ECN (Explicit Congestion Notification)</strong> <span style=\"opacity:0.75;\">(2 bits)</span>: Congestion notification (0-3)</div><div style=\"margin-bottom:7px;\"><strong>Total Length</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style=\"margin-bottom:7px;\"><strong>Identification</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Same ID for all fragments of one packet</div><div style=\"margin-bottom:7px;\"><strong>Flags</strong> <span style=\"opacity:0.75;\">(3 bits)</span>: Reserved (0), DF (Don\'t Fragment), MF (More Fragments)</div><div style=\"margin-bottom:7px;\"><strong>Fragment Offset</strong> <span style=\"opacity:0.75;\">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style=\"margin-bottom:7px;\"><strong>TTL (Time to Live)</strong> <span style=\"opacity:0.75;\">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style=\"margin-bottom:7px;\"><strong>Protocol</strong> <span style=\"opacity:0.75;\">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style=\"margin-bottom:7px;\"><strong>Header Checksum</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style=\"margin-bottom:7px;\"><strong>Source Address</strong> <span style=\"opacity:0.75;\">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style=\"margin-bottom:7px;\"><strong>Destination Address</strong> <span style=\"opacity:0.75;\">(32 bits)</span>: Receiver IPv4 address</div><div style=\"margin-bottom:7px;\"><strong>Options</strong> <span style=\"opacity:0.75;\">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style=\"margin-top:8px;\">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - IP Services (CCNA / Day 47 Flashcards - QoS (Part 2)</div></div></div>' WHERE question_no = 'Anki-IPS-4386';

-- Anki-IPS-4387
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: RFC 4594 Marking Recommendations</div><p>RFC 4594 recommends EF for voice, AF4x for interactive video, AF3x for streaming video, AF2x for high-priority data, AF1x for low-priority data, and DF for best effort.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>EF</strong>: RFC 4594 assigns voice the EF marking. The highest-priority per-hop behaviour.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>CS5</strong>: CS5 is a class selector (DSCP 40), not the RFC 4594 voice recommendation.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>DF</strong>: DF is the best-effort marking.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>AF41</strong>: AF41 is the interactive-video marking.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>RFC 4594:</p><ul><li>voice = EF.</li><li>interactive video = AF4x.</li><li>streaming video = AF3x.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - IP Services (CCNA / Day 47 Flashcards - QoS (Part 2)</div></div></div>' WHERE question_no = 'Anki-IPS-4387';

-- Anki-NA-2001
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Ethernet Frame Structure</div><p>An Ethernet frame has a header, a payload and a trailer. The header holds the Preamble, SFD (Start Frame Delimiter), Destination, Source and Type/Length fields, and the trailer holds only one field.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>FCS (Frame Check Sequence)</strong>: The FCS (Frame Check Sequence) is the only field in the Ethernet trailer. It is a 4-byte CRC (Cyclic Redundancy Check) value the receiver uses to check whether the frame arrived intact.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>SFD (Start Frame Delimiter)</strong>: The SFD is a header field that marks the end of the Preamble, not part of the trailer.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Destination MAC Address</strong>: The Destination MAC (Media Access Control) Address is a header field, not part of the trailer.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Preamble</strong>: The Preamble is a header field used for synchronization, not part of the trailer.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Remember the frame layout:</p><ul><li>header (Preamble, SFD, Destination, Source, Type/Length).</li><li>payload.</li><li>trailer (FCS only).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2001';

-- Anki-NA-2009
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Ethernet Header Fields</div><p>The Type/Length field tells the receiver whether the number that follows is a frame length or an EtherType that identifies the upper-layer protocol.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>2</strong>: The Type/Length field is 2 bytes long.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>4</strong>: 4 bytes is the size of the FCS (Frame Check Sequence) trailer, not the Type/Length field.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>6</strong>: 6 bytes is the size of the MAC (Media Access Control) address fields, not the Type/Length field.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>1</strong>: 1 byte is the size of the SFD (Start Frame Delimiter), not the Type/Length field.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Header sizes:</p><ul><li>Preamble 7.</li><li>SFD 1.</li><li>Destination 6.</li><li>Source 6.</li><li>Type/Length 2.</li><li>FCS 4.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2009';

-- Anki-NA-2020
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Ethernet EtherType Values</div><p>The Type/Length field holds an EtherType value that tells the receiver which protocol is carried inside the frame. Each common protocol has its own well-known hex value.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>0x0800 🌐 IPv4 → 0x0800 🌍 IPv6 → 0x86DD 📡 ARP → 0x0806 🏷️ VLAN → 0x8100</strong>: The Ethernet Type value for IPv4 (Internet Protocol version 4) is 0x0800. The stored answer also lists the other common values for reference: IPv6 (Internet Protocol version 6) is 0x86DD, ARP (Address Resolution Protocol) is 0x0806 and VLAN (Virtual Local Area Network) tagging is 0x8100.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>0x0806</strong>: 0x0806 is the EtherType for ARP, not IPv4.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>0x86DD</strong>: 0x86DD is the EtherType for IPv6, not IPv4.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>0x8100</strong>: 0x8100 is the EtherType that marks an 802.1Q VLAN tag, not IPv4.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorize the four:</p><ul><li>IPv4 0x0800.</li><li>IPv6 0x86DD.</li><li>ARP 0x0806.</li><li>VLAN 0x8100.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2020';

-- Anki-NA-2021
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Ethernet EtherType Values</div><p>The Type field in an Ethernet frame holds an EtherType value. It tells the receiver which protocol is carried inside the frame. Each common protocol has its own well-known hex value.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>0x86DD</strong>: The Ethernet Type value for IPv6 is 0x86DD.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>0x0800</strong>: 0x0800 is the EtherType for IPv4, not IPv6.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>0x8100</strong>: 0x8100 is the EtherType that marks an 802.1Q VLAN tag, not IPv6.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>0x0806</strong>: 0x0806 is the EtherType for ARP, not IPv6.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorize the four:</p><ul><li>IPv4 0x0800.</li><li>IPv6 0x86DD.</li><li>ARP 0x0806.</li><li>VLAN 0x8100.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2021';

-- Anki-NA-2028
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Hexadecimal Numbering</div><p>Hexadecimal is base 16. The digits 0-9 keep their decimal values, and the letters A-F stand for the values 10-15.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>10</strong>: Hexadecimal A = Decimal 10. The letters start at A = 10, B = 11, C = 12, D = 13, E = 14, F = 15.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>15</strong>: 15 is the decimal value of hex F, not of A.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>11</strong>: 11 is the decimal value of hex B, not of A.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>9</strong>: 9 is the decimal value of the hex digit 9, not of A.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Hex letters:</p><ul><li>A=10.</li><li>B=11.</li><li>C=12.</li><li>D=13.</li><li>E=14.</li><li>F=15.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2028';

-- Anki-NA-2029
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Hexadecimal Numbering</div><p>Hexadecimal is base 16. The digits 0-9 keep their decimal values, and the letters A-F stand for the values 10-15.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>11</strong>: Hexadecimal B = Decimal 11. The letters start at A = 10, B = 11, C = 12, D = 13, E = 14, F = 15.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>15</strong>: 15 is the decimal value of hex F, not of B.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>10</strong>: 10 is the decimal value of hex A, not of B.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>12</strong>: 12 is the decimal value of hex C, not of B.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Hex letters:</p><ul><li>A=10.</li><li>B=11.</li><li>C=12.</li><li>D=13.</li><li>E=14.</li><li>F=15.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2029';

-- Anki-NA-2030
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Hexadecimal Numbering</div><p>Hexadecimal is base 16. The digits 0-9 keep their decimal values, and the letters A-F stand for the values 10-15.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>12</strong>: Hexadecimal C = Decimal 12. The letters start at A = 10, B = 11, C = 12, D = 13, E = 14, F = 15.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>11</strong>: 11 is the decimal value of hex B, not of C.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>13</strong>: 13 is the decimal value of hex D, not of C.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>10</strong>: 10 is the decimal value of hex A, not of C.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Hex letters:</p><ul><li>A=10.</li><li>B=11.</li><li>C=12.</li><li>D=13.</li><li>E=14.</li><li>F=15.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2030';

