UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Hexadecimal Numbering</div><p>Hexadecimal is base 16. The digits 0-9 keep their decimal values, and the letters A-F stand for the values 10-15.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>13</strong>: Hexadecimal D = Decimal 13. The letters start at A = 10, B = 11, C = 12, D = 13, E = 14, F = 15.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>14</strong>: 14 is the decimal value of hex E, not of D.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>11</strong>: 11 is the decimal value of hex B, not of D.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>12</strong>: 12 is the decimal value of hex C, not of D.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Hex letters:</p><ul><li>A=10.</li><li>B=11.</li><li>C=12.</li><li>D=13.</li><li>E=14.</li><li>F=15.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2031';

