UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Hexadecimal Numbering</div><p>Hexadecimal is base 16. The digits 0-9 keep their decimal values, and the letters A-F stand for the values 10-15.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>14</strong>: Hexadecimal E = Decimal 14. The letters start at A = 10, B = 11, C = 12, D = 13, E = 14, F = 15.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>13</strong>: 13 is the decimal value of hex D, not of E.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>12</strong>: 12 is the decimal value of hex C, not of E.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>15</strong>: 15 is the decimal value of hex F, not of E.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Hex letters:</p><ul><li>A=10.</li><li>B=11.</li><li>C=12.</li><li>D=13.</li><li>E=14.</li><li>F=15.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2032';

-- Anki-NA-2033
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Hexadecimal Numbering</div><p>Hexadecimal is base 16. The digits 0-9 keep their decimal values, and the letters A-F stand for the values 10-15.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>15</strong>: Hexadecimal F = Decimal 15. The letters start at A = 10, B = 11, C = 12, D = 13, E = 14, F = 15.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>14</strong>: 14 is the decimal value of hex E, not of F.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>10</strong>: 10 is the decimal value of hex A, not of F.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>12</strong>: 12 is the decimal value of hex C, not of F.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Hex letters:</p><ul><li>A=10.</li><li>B=11.</li><li>C=12.</li><li>D=13.</li><li>E=14.</li><li>F=15.</li></ul><p>F is the highest single hex digit.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 05 Flashcards - Ethernet LAN Switching (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2033';

-- Anki-NA-2055
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Ethernet EtherType Values</div><p>The Type/Length field holds an EtherType value that tells the receiver which protocol is carried inside the frame. Each common protocol has its own well-known hex value.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>0x0806</strong>: The Ethernet Type code for an ARP (Address Resolution Protocol) packet is 0x0806.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>0x8100</strong>: 0x8100 is the EtherType that marks an 802.1Q VLAN (Virtual Local Area Network) tag, not ARP.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>0x86DD</strong>: 0x86DD is the EtherType for IPv6 (Internet Protocol version 6), not ARP.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>0x0800</strong>: 0x0800 is the EtherType for IPv4 (Internet Protocol version 4), not ARP.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorize the four:</p><ul><li>IPv4 0x0800.</li><li>IPv6 0x86DD.</li><li>ARP 0x0806.</li><li>VLAN 0x8100.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 06 Flashcards - Ethernet LAN Switching (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2055';

-- Anki-NA-2062
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Interface Speed and Duplex</div><p>To set a fixed speed on a switch interface you use the speed command in interface configuration mode, followed by the speed in Mbps.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>speed 100</strong>: To configure a speed of 100 Mbps on an interface: SW1(config-if)# speed 100.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>speed 1000</strong>: speed 1000 sets the interface to 1000 Mbps (1 Gbps), not 100 Mbps.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>speed auto</strong>: speed auto enables autonegotiation; it does not fix the speed at 100 Mbps.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>speed 10</strong>: speed 10 sets the interface to 10 Mbps, not 100 Mbps.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>speed <value> in interface mode:</p><ul><li>10.</li><li>100.</li><li>1000.</li><li>10000.</li><li>or auto.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 09 Flashcards - Switch Interfaces)</div></div></div>' WHERE question_no = 'Anki-NA-2062';

-- Anki-NA-2084
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: VLANs</div><p>A new Cisco switch already has some VLANs in its database before you configure anything. There are five of them, including the default VLAN (Virtual Local Area Network) and four reserved ones.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>1, 1002, 1003, 1004, 1005</strong>: The 5 VLANs that exist by default on a Cisco switch are 1, 1002, 1003, 1004, 1005. VLAN 1 is the default, and 1002-1005 are reserved for Token Ring and FDDI.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>1, 100, 200, 300, 400</strong>: VLANs 100, 200, 300 and 400 do not exist by default; the reserved ones are 1002-1005.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>1, 1002, 1003, 1004</strong>: This list is missing VLAN 1005; there are five default VLANs, not four.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>1, 2, 3, 4, 5</strong>: Only VLAN 1 exists by default among these; VLANs 2-5 must be created manually.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Default VLANs:</p><ul><li>1.</li><li>1002.</li><li>1003.</li><li>1004.</li><li>1005.</li></ul><p>Normal usable range is 1-1005, extended is 1006-4094.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 16 Flashcards - VLANs (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2084';

-- Anki-NA-2097
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: VLAN Tagging</div><p>The 802.1Q tag is a 4-byte field inserted into the Ethernet header. Its position is fixed: it goes right after one specific header field.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>Source MAC Address</strong>: The 802.1Q tag is inserted after the Source MAC (Media Access Control) Address field of the Ethernet header.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Type/Length</strong>: The tag comes before the Type/Length field, not after it.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Destination MAC Address</strong>: The tag comes after both MAC address fields, not after the Destination field alone.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>FCS</strong>: The FCS (Frame Check Sequence) is in the trailer at the end of the frame; the tag is inserted near the start of the header.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Order in the header:</p><ul><li>Destination.</li><li>Source.</li><li>802.1Q tag.</li><li>Type/Length.</li><li>payload.</li><li>FCS.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 17 Flashcards - VLANs (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2097';

-- Anki-NA-2103
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: 802.1Q Tag Fields</div><p>The TPID (Tag Protocol Identifier) is the first field of the 802.1Q tag. It tells a receiving device that the frame carries an 802.1Q tag.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>16</strong>: The TPID field is 16 bits (2 bytes) long.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>8</strong>: 8 bits is 1 byte; the TPID is 2 bytes, so 16 bits.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>12</strong>: 12 bits is the size of the VID field, not the TPID.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>32</strong>: 32 bits would be 4 bytes. That is the size of the whole 802.1Q tag, not the TPID field alone.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><ul><li>TPID = 16 bits.</li><li>PCP = 3 bits.</li><li>DEI = 1 bit.</li><li>VID = 12 bits.</li></ul><p>Together they make the 32-bit (4-byte) tag.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 17 Flashcards - VLANs (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2103';

-- Anki-NA-2107
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: 802.1Q Tag Fields</div><p>The DEI field is a single flag in the 802.1Q tag that tells a switch a frame may be dropped first if the network is congested.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>1 bit</strong>: The DEI field is 1 bit long. A single flag that is either set or clear.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>12 bits</strong>: 12 bits is the size of the VID field, not the DEI field.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>3 bits</strong>: 3 bits is the size of the PCP field, not the DEI field.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>8 bits</strong>: 8 bits is 1 byte; the DEI field is just a single bit.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><ul><li>DEI = 1 bit.</li><li>PCP = 3 bits.</li><li>VID = 12 bits.</li><li>TPID = 16 bits.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 17 Flashcards - VLANs (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2107';

-- Anki-NA-2159
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: VTP Modes</div><p>Every switch in a VTP (VLAN Trunking Protocol) domain runs in one of three modes, which decides whether it can change VLANs and whether it synchronises.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answers (Options A, C and E) are Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>Server</strong>: A VTP server can create, change and delete VLANs, and it advertises the VLAN (Virtual Local Area Network) database to clients.</li><li><span class=\"opt-tag correct\">Option C</span> <strong>client</strong>: A VTP client receives the VLAN database from a server and cannot change VLANs itself.</li><li><span class=\"opt-tag correct\">Option E</span> <strong>transparent</strong>: A VTP transparent switch keeps its own local VLAN database, can change it, but does not synchronise with servers.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>master</strong>: There is no master mode in VTP; the three modes are server, client and transparent.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>slave</strong>: There is no slave mode in VTP; the three modes are server, client and transparent.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>VTP modes:</p><ul><li>server (can change, syncs).</li><li>client (cannot change, syncs).</li><li>transparent (can change, does not sync).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 19 Flashcards - DTP &amp; VTP)</div></div></div>' WHERE question_no = 'Anki-NA-2159';

-- Anki-NA-2201
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: 802.1D STP Path Costs</div><p>The 802.1D cost table is based on link speed: 10 Mbps costs 100, 100 Mbps costs 19, 1 Gbps costs 4 and 10 Gbps costs 2. Slower links get higher costs so STP prefers faster paths.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>100</strong>: 10 Mbps is the slowest speed in the table, so it carries the highest cost of 100.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>4</strong>: 4 is the cost of a 1 Gbps link, not a 10 Mbps link.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>2</strong>: 2 is the cost of a 10 Gbps link, not a 10 Mbps link.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>19</strong>: 19 is the cost of a 100 Mbps link, not a 10 Mbps link.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the table:</p><ul><li>10 Mbps = 100.</li><li>100 Mbps = 19.</li><li>1 Gbps = 4.</li><li>10 Gbps = 2.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 20 Flashcards - STP (Part 1)</div></div></div>' WHERE question_no = 'Anki-NA-2201';

-- Anki-NA-2226
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: STP Learning State</div><p>A port in the learning state both sends and receives BPDUs, just like in the listening state. The difference between listening and learning is only MAC (Media Access Control) learning. BPDU (Bridge Protocol Data Unit) exchange is the same in both.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>Yes</strong>: A learning port both sends and receives BPDUs.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>No</strong>: A learning port must keep exchanging BPDUs to stay in sync with the topology. Only data traffic is blocked.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Only sends BPDUs</strong>: Learning ports also receive BPDUs. They need the neighbour\'s information to stay in the election.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Only receives BPDUs</strong>: Learning ports also send BPDUs. Only blocking ports are receive-only.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Learning:</p><ul><li>BPDUs in both directions.</li><li>data in neither.</li><li>MAC learning yes.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 21 Flashcards - STP (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2226';

-- Anki-NA-2229
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: STP Forwarding State</div><p>A port in the forwarding state both sends and receives BPDUs. Designated ports forward BPDUs downstream, and all forwarding ports keep exchanging BPDUs so the topology stays monitored.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>Yes</strong>: A forwarding port both sends and receives BPDUs.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>No</strong>: Forwarding ports must keep exchanging BPDUs. Without them the switch could not detect topology changes.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Only sends BPDUs</strong>: Forwarding ports also receive BPDUs from their neighbours. BPDU (Bridge Protocol Data Unit) exchange is always two-way except on blocking ports.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Only receives BPDUs</strong>: Designated ports in the forwarding state send BPDUs downstream; only blocking ports are receive-only.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Forwarding:</p><ul><li>BPDUs in both directions.</li><li>data in both directions.</li><li>MAC (Media Access Control) learning on.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 21 Flashcards - STP (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2229';

-- Anki-NA-2233
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: STP BPDU Forwarding</div><p>BPDUs are forwarded only out of designated ports. The root bridge originates them, and each switch forwards them out of its designated ports toward the rest of the network. Root ports only receive them, and non-designated ports only listen.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>designated</strong>: BPDUs are forwarded only on designated ports.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>root</strong>: The root port receives BPDUs from the root. It does not forward them onward. Forwarding BPDUs downstream is the designated port\'s job.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>non-designated</strong>: Non-designated ports are in the blocking state; they only receive BPDUs and never forward them.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>alternate</strong>: Alternate is an RSTP (Rapid Spanning Tree Protocol) role for a blocked backup port. It does not forward BPDUs.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>BPDU (Bridge Protocol Data Unit) flow:</p><ul><li>root originates.</li><li>designated ports forward.</li><li>root ports receive.</li><li>non-designated ports listen.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 21 Flashcards - STP (Part 2)</div></div></div>' WHERE question_no = 'Anki-NA-2233';

-- Anki-NA-2260
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: RSTP Port Roles</div><p>RSTP (Rapid Spanning Tree Protocol) defines four port roles: root, designated, alternate and backup. The alternate port is a backup path to the root bridge, and the backup port is a backup for a designated port. The two new roles are what let RSTP converge so fast.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Root Designated Alternate Backup</strong>: The four RSTP port roles are Root, Designated, Alternate and Backup.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Root Designated Alternate Discarding</strong>: Discarding is a port state, not a port role. The fourth role is backup.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Root Designated Backup Learning</strong>: Learning is a port state, not a port role. The fourth role is alternate.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Root Designated Non-designated Blocking</strong>: Non-designated and blocking are classic STP concepts, not RSTP roles. RSTP replaced them with alternate and backup.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>RSTP roles:</p><ul><li>Root.</li><li>Designated.</li><li>Alternate (backup root path).</li><li>Backup (backup designated port).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 22 Flashcards - Rapid STP)</div></div></div>' WHERE question_no = 'Anki-NA-2260';

-- Anki-NA-2274
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: RSTP Link Types</div><p>RSTP (Rapid Spanning Tree Protocol) defines three link types: edge (a link to an end device, which can go straight to forwarding), point-to-point (a full-duplex link to another switch, which can negotiate rapid transition) and shared (a half-duplex link, which must use slow timers).</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>Edge Point-to-point Shared</strong>: The three RSTP link types are Edge, Point-to-point and Shared.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Edge Shared Designated</strong>: Designated is a port role, not a link type. The third link type is point-to-point.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Point-to-point Shared Root</strong>: Root is a port role, not a link type. The third link type is edge.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Edge Point-to-point Designated</strong>: Designated is a port role, not a link type. The third link type is shared.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Link types:</p><ul><li>edge (end device).</li><li>point-to-point (full-duplex switch link).</li><li>shared (half-duplex).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 22 Flashcards - Rapid STP)</div></div></div>' WHERE question_no = 'Anki-NA-2274';

-- Anki-NA-2431
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: 802.11 Frame Types</div><p>There are three 802.11 frame types: Management (beacons, probes, authentication, association), Control (RTS, CTS, ACK) and Data (the actual user traffic).</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>Management Control Data</strong>: The three 802.11 frame types are Management, Control and Data.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option D</span> <strong>Management, Control, Voice</strong>: Voice is a traffic class carried inside data frames, not a frame type of its own.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Data, Voice, Video</strong>: Voice and video are types of data traffic, not 802.11 frame types; the three types are Management, Control and Data.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Beacon, Probe, Association</strong>: Beacon, probe and association are all management frames; they are subtypes, not the three frame types.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Three frame types:</p><ul><li>Management (setup).</li><li>Control (medium access).</li><li>Data (user traffic).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2431';

-- Anki-NA-2441
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Wireless AP Architectures</div><p>The three main wireless AP (Access Point) deployment methods are Autonomous (standalone APs), Lightweight (split-MAC, APs managed by a WLC) and Cloud-based (APs managed from the cloud, e.g. Meraki).</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>Autonomous Lightweight Cloud-based</strong>: The three architectures are Autonomous, Lightweight and Cloud-based.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>Autonomous, Split-MAC, Cloud-based</strong>: Split-MAC (Media Access Control) is the name of the lightweight architecture itself, not a separate third architecture.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Local, FlexConnect, Mesh</strong>: Local, FlexConnect and Mesh are lightweight AP operating modes, not the three deployment architectures.</li><li><span class=\"opt-tag wrong\">Option A</span> <strong>Standalone, Controller-based, Mesh</strong>: Mesh is an AP operating mode, not one of the three deployment architectures.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Three architectures:</p><ul><li>Autonomous (no controller).</li><li>Lightweight (WLC).</li><li>Cloud-based (cloud dashboard).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2441';

-- Anki-NA-2470
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Unified WLC Scale</div><p>A Unified WLC (Wireless LAN Controller) (a hardware appliance in a central location) can support about 6000 APs, the largest scale of the WLC types.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>6000</strong>: A Unified WLC supports about 6000 APs.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>3000</strong>: About 3000 APs is the scale of a cloud-based WLC, not a Unified WLC.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>1000</strong>: 1000 APs is below the Unified WLC\'s scale of about 6000.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>500</strong>: 500 APs is far below the Unified WLC\'s scale of about 6000.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>WLC scale ladder:</p><ul><li>Unified 6000.</li><li>Cloud-based 3000.</li><li>Embedded 200.</li><li>Mobility Express 100.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2470';

-- Anki-NA-2471
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cloud-Based WLC Scale</div><p>A cloud-based WLC (Wireless LAN Controller) (a VM in a private cloud) can support about 3000 APs. Half the scale of a Unified hardware WLC.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>3000</strong>: A cloud-based WLC supports about 3000 APs.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>6000</strong>: About 6000 APs is the scale of a Unified WLC, not a cloud-based WLC.</li><li><span class=\"opt-tag wrong\">Option A</span> <strong>200</strong>: About 200 APs is the scale of an Embedded WLC, not a cloud-based WLC.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>100</strong>: About 100 APs is the scale of a Mobility Express WLC, not a cloud-based WLC.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>WLC scale ladder:</p><ul><li>Unified 6000.</li><li>Cloud-based 3000.</li><li>Embedded 200.</li><li>Mobility Express 100.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2471';

-- Anki-NA-2472
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Embedded WLC Scale</div><p>An Embedded WLC (Wireless LAN Controller) (integrated within a switch) can support about 200 APs, suited to medium-size sites.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>200</strong>: An Embedded WLC supports about 200 APs.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>100</strong>: About 100 APs is the scale of a Mobility Express WLC, not an Embedded WLC.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>3000</strong>: About 3000 APs is the scale of a cloud-based WLC, not an Embedded WLC.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>6000</strong>: About 6000 APs is the scale of a Unified WLC, not an Embedded WLC.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>WLC scale ladder:</p><ul><li>Unified 6000.</li><li>Cloud-based 3000.</li><li>Embedded 200.</li><li>Mobility Express 100.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2472';

-- Anki-NA-2473
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Mobility Express WLC Scale</div><p>A Mobility Express WLC (Wireless LAN Controller) (integrated within an AP) can support about 100 APs, suited to small sites.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>100</strong>: A Mobility Express WLC supports about 100 APs.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>200</strong>: About 200 APs is the scale of an Embedded WLC, not a Mobility Express WLC.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>3000</strong>: About 3000 APs is the scale of a cloud-based WLC, not a Mobility Express WLC.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>6000</strong>: About 6000 APs is the scale of a Unified WLC, not a Mobility Express WLC.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>WLC scale ladder:</p><ul><li>Unified 6000.</li><li>Cloud-based 3000.</li><li>Embedded 200.</li><li>Mobility Express 100.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 56 Flashcards - Wireless Architectures)</div></div></div>' WHERE question_no = 'Anki-NA-2473';

-- Anki-NA-2497
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: EAP-FAST Phases</div><p>EAP (Extensible Authentication Protocol)-FAST works in three phases: first the PAC is provisioned, then a secure TLS tunnel is established using that PAC, and finally the client is authenticated inside the tunnel.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>Secure TLS tunnel is established</strong>: Phase 2 of EAP-FAST is the establishment of the secure TLS tunnel, built using the PAC received in phase 1.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>The client sends its credentials in clear text</strong>: Credentials are never sent in clear text in EAP-FAST; they are sent inside the encrypted TLS tunnel.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Client is authenticated via the TLS tunnel</strong>: The client being authenticated inside the tunnel is phase 3, not phase 2.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>PAC is passed from server to client</strong>: The PAC being passed is phase 1, not phase 2.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>EAP-FAST order:</p><ul><li>1) PAC.</li><li>2) TLS tunnel.</li><li>3) authentication inside the tunnel.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 57 Flashcards - Wireless Security)</div></div></div>' WHERE question_no = 'Anki-NA-2497';

-- Anki-NA-2498
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: EAP-FAST Phases</div><p>EAP (Extensible Authentication Protocol)-FAST works in three phases: first the PAC is provisioned, then a secure TLS tunnel is established using that PAC, and finally the client is authenticated inside the tunnel.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>Client is authenticated via the TLS tunnel</strong>: Phase 3 of EAP-FAST is the client being authenticated via the TLS tunnel that was established in phase 2.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>PAC is passed from server to client</strong>: The PAC being passed is phase 1, not phase 3.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>The server is authenticated via a certificate</strong>: Server authentication via a certificate is how PEAP works, not EAP-FAST phase 3.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Secure TLS tunnel is established</strong>: The TLS tunnel being established is phase 2, not phase 3.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>EAP-FAST order:</p><ul><li>1) PAC.</li><li>2) TLS tunnel.</li><li>3) authentication inside the tunnel.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 57 Flashcards - Wireless Security)</div></div></div>' WHERE question_no = 'Anki-NA-2498';

-- Anki-NA-2546
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: WLAN Platinum QoS</div><p>WLC (Wireless LAN Controller) QoS (Quality of Service) profiles map to traffic types: Platinum is the highest priority and is meant for voice traffic, which needs low delay and jitter.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>voice</strong>: WLAN Platinum QoS = voice.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>background</strong>: Background traffic uses the Bronze profile, not Platinum.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>video</strong>: Video uses the Gold profile, not Platinum.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>best effort</strong>: Best effort uses the Silver profile, not Platinum.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><ul><li>Platinum = voice.</li><li>Gold = video.</li><li>Silver = best effort.</li><li>Bronze = background.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 58 Flashcards - Wireless Configuration)</div></div></div>' WHERE question_no = 'Anki-NA-2546';

-- Anki-NA-2547
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: WLAN Gold QoS</div><p>WLC (Wireless LAN Controller) QoS (Quality of Service) profiles map to traffic types: Gold is the second-highest profile and is meant for video traffic, which needs good bandwidth and low delay.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>video</strong>: WLAN Gold QoS = video.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>voice</strong>: Voice uses the Platinum profile, not Gold.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>background</strong>: Background traffic uses the Bronze profile, not Gold.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>best effort</strong>: Best effort uses the Silver profile, not Gold.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><ul><li>Platinum = voice.</li><li>Gold = video.</li><li>Silver = best effort.</li><li>Bronze = background.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 58 Flashcards - Wireless Configuration)</div></div></div>' WHERE question_no = 'Anki-NA-2547';

-- Anki-NA-2549
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: WLAN Bronze QoS</div><p>WLC (Wireless LAN Controller) QoS (Quality of Service) profiles map to traffic types: Bronze is the lowest priority profile and is meant for background traffic, which can wait when the network is busy.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>background</strong>: WLAN Bronze QoS = background.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>video</strong>: Video uses the Gold profile, not Bronze.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>best effort</strong>: Best effort uses the Silver profile, not Bronze.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>voice</strong>: Voice uses the Platinum profile, not Bronze.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><ul><li>Platinum = voice.</li><li>Gold = video.</li><li>Silver = best effort.</li><li>Bronze = background.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 58 Flashcards - Wireless Configuration)</div></div></div>' WHERE question_no = 'Anki-NA-2549';

-- Anki-NA-2551
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: WLAN Video QoS</div><p>WLC (Wireless LAN Controller) QoS (Quality of Service) profiles map to traffic types: video traffic needs good bandwidth and low delay, so it gets the Gold profile, second only to voice.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>Gold</strong>: WLAN Gold QoS = video.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>Bronze</strong>: Bronze is the background profile, not the video profile.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Platinum</strong>: Platinum is the voice profile, not the video profile.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Silver</strong>: Silver is the best effort profile, not the video profile.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Video = Gold.</p><ul><li>Voice = Platinum.</li><li>video = Gold.</li><li>best effort = Silver.</li><li>background = Bronze.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 58 Flashcards - Wireless Configuration)</div></div></div>' WHERE question_no = 'Anki-NA-2551';

-- Anki-NA-2553
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: WLAN Background QoS</div><p>WLC (Wireless LAN Controller) QoS (Quality of Service) profiles map to traffic types: background traffic is the lowest priority and can wait, so it uses the Bronze profile.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>Bronze</strong>: WLAN Bronze QoS = background.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Platinum</strong>: Platinum is the voice profile, not the background profile.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Gold</strong>: Gold is the video profile, not the background profile.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Silver</strong>: Silver is the best effort profile, not the background profile.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Background = Bronze.</p><ul><li>Platinum = voice.</li><li>Gold = video.</li><li>Silver = best effort.</li><li>Bronze = background.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Access (CCNA / Day 58 Flashcards - Wireless Configuration)</div></div></div>' WHERE question_no = 'Anki-NA-2553';

-- Anki-NF-1003
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Network Device Symbols - Router</div><p>Network diagrams use standard symbols for each device. A router is drawn as a circle with four arrows pointing in and out, showing that it forwards traffic between different networks.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>Router</strong>: The symbol in the exhibit is the standard router symbol. A router connects different networks together and forwards packets between them using logical (IP) addressing.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Switch</strong>: A switch connects hosts inside the same LAN and forwards frames using MAC (Media Access Control) addresses; its symbol is different.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Firewall</strong>: A firewall filters traffic based on rules; its symbol is a brick wall, not a circle with arrows.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Server</strong>: A server provides services to clients; it is drawn as a rack or tower, not as a circle with arrows.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Learn the diagram symbols:</p><ul><li>router = circle with arrows.</li><li>switch = rectangle with crossing arrows.</li><li>firewall = brick wall.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1003';

-- Anki-NF-1014
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cisco Catalyst</div><p>Cisco Catalyst is Cisco\'s family of Ethernet switches, used to build LANs in offices and campuses. The name Catalyst is a brand of switch, not a separate device type.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>Switch</strong>: A Cisco Catalyst is a switch. The Catalyst line (for example Catalyst 2960 and 9300) are all LAN switches.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option C</span> <strong>Router</strong>: Cisco routers are the ISR and ASR families, not Catalyst.</li><li><span class=\"opt-tag wrong\">Option A</span> <strong>Firewall</strong>: Cisco firewalls are the ASA and Firepower families, not Catalyst.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Wireless controller</strong>: Wireless controllers manage access points; Catalyst devices switch wired traffic.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Cisco naming:</p><ul><li>Catalyst = switch.</li><li>ISR/ASR = router.</li><li>ASA/Firepower = firewall.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1014';

-- Anki-NF-1020
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cisco ASA</div><p>Cisco ASA stands for Adaptive Security Appliance. It is Cisco\'s classic firewall platform, used to protect a network edge by filtering traffic and providing VPN (Virtual Private Network) access.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>Firewall</strong>: A Cisco ASA is a firewall. ASA is Cisco\'s firewall product line, built to inspect and control traffic at the network edge.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>Router</strong>: Cisco routers are the ISR and ASR families, not ASA.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Switch</strong>: Cisco switches are the Catalyst family, not ASA.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>VPN concentrator</strong>: An ASA can provide VPN, but its device type is a firewall, not a standalone VPN concentrator.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Cisco naming:</p><ul><li>ASA = firewall.</li><li>Catalyst = switch.</li><li>ISR/ASR = router.</li><li>Firepower = next-generation firewall.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 01 Flashcards - Network Devices)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1020';

-- Anki-NF-1028
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Megabit</div><p>In networking, mega means one million (1,000,000). So a 100 Mbps link carries 100 million bits per second.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>1,000,000 (1 million)</strong>: 1 megabit is 1,000,000 bits (1 million). Networking uses decimal prefixes throughout.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>1,048,576</strong>: 1,048,576 is 2^20. The binary value used for memory (1 MiB), not the decimal megabit used in networking.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>100,000</strong>: One hundred thousand bits is 100 kilobits, not 1 megabit.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>10,000,000</strong>: Ten million bits is 10 megabits, not 1 megabit.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Mega = 1,000,000 in networking.</p><ul><li>Kilo = 1,000.</li><li>mega = 1,000,000.</li><li>giga = 1,000,000,000.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1028';

-- Anki-NF-1030
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Terabit</div><p>In networking, tera means one trillion (1,000,000,000,000). Terabit speeds appear on high-end backbone and data-centre links.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>1,000,000,000,000 (1 trillion)</strong>: 1 terabit is 1,000,000,000,000 bits (1 trillion). Networking uses the decimal definition.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>1,099,511,627,776</strong>: 1,099,511,627,776 is 2^40. The binary value used for memory (1 TiB), not the decimal terabit used in networking.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>100,000,000,000</strong>: One hundred billion bits is 100 gigabits, not 1 terabit.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>10,000,000,000,000</strong>: Ten trillion bits is 10 terabits, not 1 terabit.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The pattern is always ×1,000:</p><ul><li>kilo 10^3.</li><li>mega 10^6.</li><li>giga 10^9.</li><li>tera 10^12.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1030';

-- Anki-NF-1033
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Ethernet Speed - 10 Mbps</div><p>Plain \"Ethernet\" (10BASE-T) runs at 10 Mbps. Faster variants add a word in front: FastEthernet is 100 Mbps and Gigabit Ethernet is 1,000 Mbps.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>10 Mbps</strong>: An Ethernet connection runs at 10 Mbps. That is the original 10BASE-T speed from the 1990s.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>100 Mbps</strong>: 100 Mbps is FastEthernet, not plain Ethernet.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>1 Mbps</strong>: No standard Ethernet variant runs at 1 Mbps.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>1 Gbps</strong>: 1 Gbps is Gigabit Ethernet, a much later and faster standard.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><ul><li>Ethernet = 10.</li><li>FastEthernet = 100.</li><li>Gigabit = 1,000.</li><li>10 Gig = 10,000 Mbps.</li></ul><p>Learn the ladder.</p></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1033';

-- Anki-NF-1037
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IEEE 802.3i - 10BASE-T</div><p>Each Ethernet speed has its own IEEE 802.3 letter suffix: 802.3i is 10 Mbps over twisted pair (10BASE-T), 802.3u is 100 Mbps, 802.3ab is 1 Gbps over copper and 802.3an is 10 Gbps over copper.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>802.3i</strong>: IEEE 802.3i defines 10 Mbps Ethernet over twisted pair (10BASE-T).</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>802.3u</strong>: 802.3u defines 100 Mbps Ethernet (100BASE-T), not 10 Mbps.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>802.3ab</strong>: 802.3ab defines 1 Gbps Ethernet over copper (1000BASE-T).</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>802.3z</strong>: 802.3z defines 1 Gbps Ethernet over fiber (1000BASE-SX/LX).</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the suffixes:</p><ul><li>i = 10 Mbps.</li><li>u = 100 Mbps.</li><li>ab = 1 Gbps copper.</li><li>an = 10 Gbps copper.</li><li>ae = 10 Gbps fiber.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 02 Flashcards - Interfaces and Cables)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1037';

-- Anki-NF-1080
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI - Open Systems Interconnection</div><p>The OSI model is the 7-layer reference model that describes how data moves from an application on one device to an application on another. It was created by the ISO to standardise networking.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Open Systems Interconnection</strong>: OSI stands for Open Systems Interconnection. The reference model with 7 layers.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option D</span> <strong>Open Source Interconnection</strong>: OSI has nothing to do with open-source software; \"Open\" refers to open systems that can interconnect.</li><li><span class=\"opt-tag wrong\">Option A</span> <strong>Operating Systems Interconnection</strong>: Operating systems are software on a device; OSI is a networking model, not an operating-system term.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Open Systems Internetwork</strong>: The last word is Interconnection, not Internetwork. The model is about systems interconnecting.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>OSI = Open Systems Interconnection. 7 layers:</p><ul><li>Application.</li><li>Presentation.</li><li>Session.</li><li>Transport.</li><li>Network.</li><li>Data Link.</li><li>Physical.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1080';

-- Anki-NF-1099
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI PDUs - Layer 3 Packet</div><p>Each OSI layer has its own Protocol Data Unit (PDU) name: bits at Layer 1, frames at Layer 2, packets at Layer 3, segments at Layer 4 and data at Layers 5-7.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Packet</strong>: The Layer 3 PDU (Protocol Data Unit) is called a packet, because the Network layer encapsulates data with a logical (IP) address into a packet for routing.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Segment</strong>: A segment is the Layer 4 (Transport) PDU, created by TCP (Transmission Control Protocol) or UDP (User Datagram Protocol). Not the Layer 3 PDU.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Bits</strong>: Bits are the Layer 1 (Physical) PDU, the raw 1s and 0s on the wire. Not the Layer 3 PDU.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Frame</strong>: A frame is the Layer 2 (Data Link) PDU, which carries MAC (Media Access Control) addresses. Not the Layer 3 PDU.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the PDU ladder:</p><ul><li>Bits.</li><li>Frames.</li><li>Packets.</li><li>Segments.</li><li>Data.</li></ul><p>It is a guaranteed exam question.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1099';

-- Anki-NF-1100
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI PDUs - Layer 2 Frame</div><p>Each OSI layer has its own Protocol Data Unit (PDU) name: bits at Layer 1, frames at Layer 2, packets at Layer 3, segments at Layer 4 and data at Layers 5-7.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>Frame</strong>: The Layer 2 PDU (Protocol Data Unit) is called a frame, because the Data Link layer encapsulates a packet with source and destination MAC (Media Access Control) addresses into a frame for delivery on the local network.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Packet</strong>: A packet is the Layer 3 (Network) PDU, which carries logical IP (Internet Protocol) addresses. Not the Layer 2 PDU.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Segment</strong>: A segment is the Layer 4 (Transport) PDU, created by TCP (Transmission Control Protocol) or UDP (User Datagram Protocol). Not the Layer 2 PDU.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Bits</strong>: Bits are the Layer 1 (Physical) PDU, the raw 1s and 0s on the wire. Not the Layer 2 PDU.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the PDU ladder:</p><ul><li>Bits.</li><li>Frames.</li><li>Packets.</li><li>Segments.</li><li>Data.</li></ul><p>It is a guaranteed exam question.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1100';

-- Anki-NF-1105
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI PDUs - Layer 1 Bits</div><p>Each OSI layer has its own Protocol Data Unit (PDU) name: bits at Layer 1, frames at Layer 2, packets at Layer 3, segments at Layer 4 and data at Layers 5-7.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Bits</strong>: The Layer 1 PDU (Protocol Data Unit) is called bits, because the Physical layer transmits data as a stream of raw 1s and 0s (electrical, optical or radio signals).</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Frame</strong>: A frame is the Layer 2 (Data Link) PDU, which carries MAC (Media Access Control) addresses. Not the Layer 1 PDU.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Packet</strong>: A packet is the Layer 3 (Network) PDU, which carries logical IP (Internet Protocol) addresses. Not the Layer 1 PDU.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Segment</strong>: A segment is the Layer 4 (Transport) PDU, created by TCP (Transmission Control Protocol) or UDP (User Datagram Protocol). Not the Layer 1 PDU.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the PDU ladder:</p><ul><li>Bits.</li><li>Frames.</li><li>Packets.</li><li>Segments.</li><li>Data.</li></ul><p>It is a guaranteed exam question.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1105';

-- Anki-NF-1113
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI vs TCP/IP - Application Layer Mapping</div><p>The TCP (Transmission Control Protocol)/IP (Internet Protocol) model has only four layers, so it collapses the top three OSI layers (Application, Presentation, Session) into a single TCP/IP Application layer.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answers are Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>Application</strong>: Application is OSI Layer 7, the top layer, and it maps to the TCP/IP Application layer.</li><li><span class=\"opt-tag correct\">Option B</span> <strong>Presentation</strong>: Presentation is OSI Layer 6, and it maps to the TCP/IP Application layer.</li><li><span class=\"opt-tag correct\">Option C</span> <strong>Session</strong>: Session is OSI Layer 5, and it maps to the TCP/IP Application layer.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option D</span> <strong>Transport</strong>: Transport is OSI Layer 4, which maps to the TCP/IP Transport layer. Not to the Application layer.</li><li><span class=\"opt-tag wrong\">Option E</span> <strong>Network</strong>: Network is OSI Layer 3, which maps to the TCP/IP Internet layer. Not to the Application layer.</li><li><span class=\"opt-tag wrong\">Option F</span> <strong>Data Link</strong>: Data Link is OSI Layer 2, which maps to the TCP/IP Link layer. Not to the Application layer.</li><li><span class=\"opt-tag wrong\">Option G</span> <strong>Physical</strong>: Physical is OSI Layer 1, which maps to the TCP/IP Link layer. Not to the Application layer.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the mapping:</p><ul><li>OSI 7+6+5 = TCP/IP Application.</li><li>OSI 4 = Transport.</li><li>OSI 3 = Internet.</li><li>OSI 2+1 = Link.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1113';

-- Anki-NF-1115
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI vs TCP/IP - Internet Layer Mapping</div><p>The TCP (Transmission Control Protocol)/IP (Internet Protocol) Internet layer corresponds to OSI Layer 3 (Network). Both layers handle logical addressing and routing of packets between networks.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Network</strong>: Network is correct because OSI Layer 3 (Network) maps to the TCP/IP Internet layer. Both are the routing layer of their model.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Link</strong>: Link is a TCP/IP layer that corresponds to OSI Layers 2 and 1. Not to OSI Layer 3.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Application</strong>: Application is OSI Layer 7, which maps to the TCP/IP Application layer. Not to the Internet layer.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Transport</strong>: Transport is OSI Layer 4, which maps to the TCP/IP Transport layer. Not to the Internet layer.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the mapping:</p><ul><li>OSI 7+6+5 = TCP/IP Application.</li><li>OSI 4 = Transport.</li><li>OSI 3 = Internet.</li><li>OSI 2+1 = Link.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1115';

-- Anki-NF-1116
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI vs TCP/IP - Link Layer Mapping</div><p>The TCP (Transmission Control Protocol)/IP (Internet Protocol) Link layer (also called Network Access) corresponds to the bottom two OSI layers: Data Link (Layer 2) and Physical (Layer 1). Together they handle local delivery and the physical medium.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answers are Correct:</h4><ul><li><span class=\"opt-tag correct\">Option F</span> <strong>Data Link</strong>: Data Link is OSI Layer 2 and it maps to the TCP/IP Link layer.</li><li><span class=\"opt-tag correct\">Option G</span> <strong>Physical</strong>: Physical is OSI Layer 1 and it maps to the TCP/IP Link layer.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Application</strong>: Application is OSI Layer 7, which maps to the TCP/IP Application layer. Not to the Link layer.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Presentation</strong>: Presentation is OSI Layer 6, which maps to the TCP/IP Application layer. Not to the Link layer.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Session</strong>: Session is OSI Layer 5, which maps to the TCP/IP Application layer. Not to the Link layer.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Transport</strong>: Transport is OSI Layer 4, which maps to the TCP/IP Transport layer. Not to the Link layer.</li><li><span class=\"opt-tag wrong\">Option E</span> <strong>Network</strong>: Network is OSI Layer 3, which maps to the TCP/IP Internet layer. Not to the Link layer.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the mapping:</p><ul><li>OSI 7+6+5 = TCP/IP Application.</li><li>OSI 4 = Transport.</li><li>OSI 3 = Internet.</li><li>OSI 2+1 = Link.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1116';

-- Anki-NF-1117
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI Layers 7, 6, 5 = TCP/IP Application Layer</div><p>The TCP (Transmission Control Protocol)/IP (Internet Protocol) model collapses the top three OSI layers (Application, Presentation, Session) into one Application layer. Anything an application does. Formatting, encryption, session management. Happens in this single TCP/IP layer.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Application</strong>: Application is correct because OSI Layers 7, 6 and 5 together equal the TCP/IP Application layer.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Session</strong>: Session is only one of the three OSI layers (Layer 5) that make up the TCP/IP Application layer. The question asks for the TCP/IP layer name, which is Application.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Network</strong>: Network is OSI Layer 3, which maps to the TCP/IP Internet layer. It is not part of the Application layer.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Transport</strong>: Transport is OSI Layer 4, which maps to the TCP/IP Transport layer. It is a separate layer, not part of the Application layer.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the mapping:</p><ul><li>OSI 7+6+5 = TCP/IP Application.</li><li>OSI 4 = Transport.</li><li>OSI 3 = Internet.</li><li>OSI 2+1 = Link.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1117';

-- Anki-NF-1119
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI Network Layer = TCP/IP Internet Layer</div><p>The TCP (Transmission Control Protocol)/IP (Internet Protocol) Internet layer is the routing layer, corresponding to OSI Layer 3 (Network). Both handle logical (IP) addressing and forward packets between networks.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>Internet</strong>: Internet is correct because OSI Layer 3 (Network) maps to the TCP/IP Internet layer.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>Application</strong>: Application is the TCP/IP layer that corresponds to OSI Layers 7, 6 and 5. Not to OSI Layer 3.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Link</strong>: Link is the TCP/IP layer that corresponds to OSI Layers 2 and 1. Not to OSI Layer 3.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Transport</strong>: Transport is the TCP/IP layer that corresponds to OSI Layer 4. Not to OSI Layer 3.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the mapping:</p><ul><li>OSI 7+6+5 = TCP/IP Application.</li><li>OSI 4 = Transport.</li><li>OSI 3 = Internet.</li><li>OSI 2+1 = Link.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1119';

-- Anki-NF-1120
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI Data Link and Physical = TCP/IP Link Layer</div><p>The TCP (Transmission Control Protocol)/IP (Internet Protocol) Link layer (also called Network Access) covers the bottom two OSI layers: Data Link (Layer 2, framing and MAC addressing) and Physical (Layer 1, bits and signals).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>Link</strong>: Link is correct because OSI Layers 2 (Data Link) and 1 (Physical) together map to the TCP/IP Link layer.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Internet</strong>: Internet is the TCP/IP layer that corresponds to OSI Layer 3 (Network). Not to Layers 2 and 1.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Application</strong>: Application is the TCP/IP layer that corresponds to OSI Layers 7, 6 and 5. Not to Layers 2 and 1.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Transport</strong>: Transport is the TCP/IP layer that corresponds to OSI Layer 4. Not to Layers 2 and 1.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the mapping:</p><ul><li>OSI 7+6+5 = TCP/IP Application.</li><li>OSI 4 = Transport.</li><li>OSI 3 = Internet.</li><li>OSI 2+1 = Link.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1120';

-- Anki-NF-1123
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Console Port Default Settings - Baud Rate</div><p>The default console port settings on a Cisco device are: 9600 bits per second, 8 data bits, no parity, 1 stop bit, and no flow control. These are remembered as 9600-8-N-1.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>9600 bits per second</strong>: 9600 bits per second is correct because the default console speed (baud rate) on Cisco devices is 9600 bps.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>115200 bits per second</strong>: 115200 bps is a common high speed for newer devices, but the classic default is 9600.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>19200 bits per second</strong>: 19200 bps is a valid speed you can configure, but it is not the default.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>1200 bits per second</strong>: 1200 bps is an old modem speed. It is not the default Cisco console speed.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise &quot;9600-8-N-1&quot;:</p><ul><li>speed 9600.</li><li>8 data bits.</li><li>no parity.</li><li>1 stop bit.</li><li>no flow control.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1123';

-- Anki-NF-1124
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Console Port Default Settings - Data Bits</div><p>The default console port settings on a Cisco device are: 9600 bits per second, 8 data bits, no parity, 1 stop bit, and no flow control. These are remembered as 9600-8-N-1.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>8</strong>: 8 is correct because the default number of data bits on a Cisco console port is 8.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>5</strong>: 5 data bits is used by very old teletype equipment, not by Cisco console ports.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>10</strong>: 10 is not a valid data-bits setting. Data bits are typically 5, 6, 7 or 8.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>7</strong>: 7 data bits is an older terminal setting, but Cisco console ports default to 8 data bits.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise &quot;9600-8-N-1&quot;:</p><ul><li>speed 9600.</li><li>8 data bits.</li><li>no parity.</li><li>1 stop bit.</li><li>no flow control.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1124';

-- Anki-NF-1125
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Console Port Default Settings - Stop Bits</div><p>The default console port settings on a Cisco device are: 9600 bits per second, 8 data bits, no parity, 1 stop bit, and no flow control. These are remembered as 9600-8-N-1.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>1</strong>: 1 is correct because the default number of stop bits on a Cisco console port is 1.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>0</strong>: 0 stop bits is not a valid setting. A stop bit is required to mark the end of each character.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>1.5</strong>: 1.5 stop bits is an old teletype setting, not the Cisco console default.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>2</strong>: 2 stop bits is a valid setting on some equipment, but Cisco console ports default to 1 stop bit.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise &quot;9600-8-N-1&quot;:</p><ul><li>speed 9600.</li><li>8 data bits.</li><li>no parity.</li><li>1 stop bit.</li><li>no flow control.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1125';

-- Anki-NF-1126
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Console Port Default Settings - Parity</div><p>The default console port settings on a Cisco device are: 9600 bits per second, 8 data bits, no parity, 1 stop bit, and no flow control. These are remembered as 9600-8-N-1.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>None</strong>: None is correct because the default parity on a Cisco console port is none. No parity bit is used.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Mark</strong>: Mark parity is an uncommon setting and is never the Cisco console default.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Even</strong>: Even parity is a valid parity setting, but it is not the Cisco console default.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Odd</strong>: Odd parity is a valid parity setting, but it is not the Cisco console default.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise &quot;9600-8-N-1&quot;:</p><ul><li>speed 9600.</li><li>8 data bits.</li><li>no parity.</li><li>1 stop bit.</li><li>no flow control.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1126';

-- Anki-NF-1127
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Console Port Default Settings - Flow Control</div><p>The default console port settings on a Cisco device are: 9600 bits per second, 8 data bits, no parity, 1 stop bit, and no flow control. These are remembered as 9600-8-N-1.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>None</strong>: None is correct because the default flow control on a Cisco console port is none. No flow control is used.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Hardware</strong>: Hardware flow control (RTS/CTS) is a valid option, but it is not the Cisco console default.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>XON/XOFF</strong>: XON/XOFF is a form of software flow control. It is not the default, which is no flow control.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Software</strong>: Software flow control (XON/XOFF) is a valid option, but it is not the Cisco console default.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise &quot;9600-8-N-1&quot;:</p><ul><li>speed 9600.</li><li>8 data bits.</li><li>no parity.</li><li>1 stop bit.</li><li>no flow control.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1127';

-- Anki-NF-1128
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cisco IOS Modes - User EXEC Prompt</div><p>Cisco IOS has a hierarchy of modes. User EXEC mode is the lowest level and is indicated by the greater-than sign (&gt;) after the hostname, for example Router&gt;. It allows only basic viewing commands.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>&gt;</strong>: &gt; is correct because the user EXEC mode prompt ends with the greater-than sign, as in Router&gt;.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>(config)#</strong>: The (config)# prompt indicates global configuration mode, which is reached from privileged EXEC mode.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>#</strong>: The hash sign (#) indicates privileged EXEC mode, which is a higher level than user EXEC mode.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>(config-if)#</strong>: The (config-if)# prompt indicates interface configuration mode, a sub-mode of global configuration.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Prompt symbols are an exam favourite:</p><ul><li>&gt; means user EXEC.</li><li># means privileged EXEC.</li><li>(config)# means global configuration.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1128';

-- Anki-NF-1129
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cisco IOS Modes - Privileged EXEC Prompt</div><p>Cisco IOS has a hierarchy of modes. Privileged EXEC mode is indicated by the hash sign (#) after the hostname, for example Router#. It allows full viewing of the configuration and access to configuration modes.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>#</strong>: # is correct because the privileged EXEC mode prompt ends with the hash sign, as in Router#.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>(config-if)#</strong>: The (config-if)# prompt indicates interface configuration mode, a sub-mode of global configuration.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>&gt;</strong>: The greater-than sign (&gt;) indicates user EXEC mode, the lowest level. Not privileged EXEC mode.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>(config)#</strong>: The (config)# prompt indicates global configuration mode, which is entered from privileged EXEC mode.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Prompt symbols are an exam favourite:</p><ul><li>&gt; means user EXEC.</li><li># means privileged EXEC.</li><li>(config)# means global configuration.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1129';

-- Anki-NF-1130
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cisco IOS Modes - Global Configuration Prompt</div><p>Cisco IOS has a hierarchy of modes. Global configuration mode is entered from privileged EXEC mode with the &quot;configure terminal&quot; command, and its prompt is Router(config)#.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>(config)#</strong>: (config)# is correct because the global configuration mode prompt shows (config)# after the hostname.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Router#</strong>: Router# is the privileged EXEC mode prompt. You must type &quot;configure terminal&quot; from here to reach global configuration.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Router(config-if)#</strong>: Router(config-if)# is the interface configuration prompt, a sub-mode entered from global configuration.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Router&gt;</strong>: Router&gt; is the user EXEC mode prompt, the lowest level. Not global configuration mode.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Prompt symbols are an exam favourite:</p><ul><li>&gt; means user EXEC.</li><li># means privileged EXEC.</li><li>(config)# means global configuration.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1130';

-- Anki-NF-1131
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cisco IOS Modes - Lowest Level</div><p>Cisco IOS modes form a hierarchy: user EXEC mode is the lowest, then privileged EXEC mode, then global configuration mode, then sub-modes such as interface configuration. Higher modes give you more power.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>user EXEC mode</strong>: user EXEC mode is correct because it is the lowest-level mode in Cisco IOS. You enter it first when you log in, and it only allows basic show commands.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>global configuration mode</strong>: Global configuration mode is a high-level mode used to change the device configuration. Not the lowest.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>interface configuration mode</strong>: Interface configuration mode is a sub-mode of global configuration. It is near the top of the hierarchy, not the bottom.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>privileged EXEC mode</strong>: Privileged EXEC mode is one level above user EXEC mode, not the lowest level.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Think of it as a ladder:</p><ul><li>user EXEC at the bottom.</li><li>privileged EXEC in the middle.</li><li>global configuration at the top.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1131';

-- Anki-NF-1146
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Password Encryption Types - Type 7</div><p>Cisco password encryption types: type 0 is clear text, type 5 is MD5 (enable secret), and type 7 is the weak reversible encryption used by &quot;service password-encryption&quot;.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>7</strong>: 7 is correct because the &quot;service password-encryption&quot; command uses type 7 encryption.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>9</strong>: Type 9 is scrypt hashing used by newer &quot;enable secret&quot; implementations; it is not the type used by service password-encryption.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>0</strong>: Type 0 means the password is stored in clear text. It is not an encryption type at all.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>5</strong>: Type 5 is MD5 encryption, used by &quot;enable secret&quot;. Not by &quot;service password-encryption&quot;.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Remember the numbers:</p><ul><li>0 = clear text.</li><li>5 = MD5 (enable secret).</li><li>7 = weak reversible (service password-encryption).</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1146';

-- Anki-NF-1147
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Password Encryption Types - Type 5 (MD5)</div><p>Cisco password encryption types: type 0 is clear text, type 5 is MD5 (enable secret), and type 7 is the weak reversible encryption used by &quot;service password-encryption&quot;.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>5</strong>: 5 is correct because &quot;enable secret&quot; uses type 5 (MD5) encryption.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>7</strong>: Type 7 is the weak reversible encryption used by &quot;service password-encryption&quot;. Not by &quot;enable secret&quot;.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>0</strong>: Type 0 means the password is stored in clear text. It is not an encryption type at all.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>8</strong>: Type 8 is PBKDF2 hashing used by newer IOS versions; the classic &quot;enable secret&quot; type is 5 (MD5).</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Remember the numbers:</p><ul><li>0 = clear text.</li><li>5 = MD5 (enable secret).</li><li>7 = weak reversible (service password-encryption).</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 04 Flashcards - Intro to the CLI)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1147';

-- Anki-NF-1153
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class A First Octet</div><p>IPv4 (Internet Protocol version 4) addresses are divided into classes by the first octet: Class A is 0-127, Class B is 128-191, Class C is 192-223, Class D is 224-239 (multicast), and Class E is 240-255 (experimental).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>0-127</strong>: 0-127 is correct because the first octet of a Class A IPv4 address ranges from 0 to 127.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>128-191</strong>: 128-191 is the first-octet range for Class B addresses, not Class A.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>192-223</strong>: 192-223 is the first-octet range for Class C addresses, not Class A.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>224-239</strong>: 224-239 is the first-octet range for Class D (multicast) addresses, not Class A.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The class boundaries are the exam favourite:</p><ul><li>A = 0-127.</li><li>B = 128-191.</li><li>C = 192-223.</li><li>D = 224-239.</li><li>E = 240-255.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1153';

-- Anki-NF-1154
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class B First Octet</div><p>IPv4 (Internet Protocol version 4) addresses are divided into classes by the first octet: Class A is 0-127, Class B is 128-191, Class C is 192-223, Class D is 224-239 (multicast), and Class E is 240-255 (experimental).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>128-191</strong>: 128-191 is correct because the first octet of a Class B IPv4 address ranges from 128 to 191.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>224-239</strong>: 224-239 is the first-octet range for Class D (multicast) addresses, not Class B.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>0-127</strong>: 0-127 is the first-octet range for Class A addresses, not Class B.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>192-223</strong>: 192-223 is the first-octet range for Class C addresses, not Class B.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The class boundaries are the exam favourite:</p><ul><li>A = 0-127.</li><li>B = 128-191.</li><li>C = 192-223.</li><li>D = 224-239.</li><li>E = 240-255.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1154';

-- Anki-NF-1155
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class C First Octet</div><p>IPv4 (Internet Protocol version 4) addresses are divided into classes by the first octet: Class A is 0-127, Class B is 128-191, Class C is 192-223, Class D is 224-239 (multicast), and Class E is 240-255 (experimental).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>192-223</strong>: 192-223 is correct because the first octet of a Class C IPv4 address ranges from 192 to 223.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>0-127</strong>: 0-127 is the first-octet range for Class A addresses, not Class C.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>224-239</strong>: 224-239 is the first-octet range for Class D (multicast) addresses, not Class C.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>128-191</strong>: 128-191 is the first-octet range for Class B addresses, not Class C.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The class boundaries are the exam favourite:</p><ul><li>A = 0-127.</li><li>B = 128-191.</li><li>C = 192-223.</li><li>D = 224-239.</li><li>E = 240-255.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1155';

-- Anki-NF-1156
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class D First Octet</div><p>IPv4 (Internet Protocol version 4) addresses are divided into classes by the first octet: Class A is 0-127, Class B is 128-191, Class C is 192-223, Class D is 224-239 (multicast), and Class E is 240-255 (experimental).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>224-239</strong>: 224-239 is correct because the first octet of a Class D IPv4 address ranges from 224 to 239.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>128-191</strong>: 128-191 is the first-octet range for Class B addresses, not Class D.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>240-255</strong>: 240-255 is the first-octet range for Class E (experimental) addresses, not Class D.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>192-223</strong>: 192-223 is the first-octet range for Class C addresses, not Class D.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The class boundaries are the exam favourite:</p><ul><li>A = 0-127.</li><li>B = 128-191.</li><li>C = 192-223.</li><li>D = 224-239.</li><li>E = 240-255.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1156';

-- Anki-NF-1157
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class E First Octet</div><p>IPv4 (Internet Protocol version 4) addresses are divided into classes by the first octet: Class A is 0-127, Class B is 128-191, Class C is 192-223, Class D is 224-239 (multicast), and Class E is 240-255 (experimental).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>240-255</strong>: 240-255 is correct because the first octet of a Class E IPv4 address ranges from 240 to 255.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>224-239</strong>: 224-239 is the first-octet range for Class D (multicast) addresses, not Class E.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>192-223</strong>: 192-223 is the first-octet range for Class C addresses, not Class E.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>0-127</strong>: 0-127 is the first-octet range for Class A addresses, not Class E.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The class boundaries are the exam favourite:</p><ul><li>A = 0-127.</li><li>B = 128-191.</li><li>C = 192-223.</li><li>D = 224-239.</li><li>E = 240-255.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1157';

-- Anki-NF-1158
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class A Binary Pattern</div><p>Each IPv4 (Internet Protocol version 4) address class has a leading-bit pattern in the first octet: Class A starts with 0 (0xxxxxxx), Class B starts with 10 (10xxxxxx), Class C starts with 110 (110xxxxx), Class D starts with 1110 (1110xxxx), and Class E starts with 1111 (1111xxxx).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>0xxxxxxx</strong>: 0xxxxxxx is correct because the first octet of a Class A address starts with a 0 bit, followed by seven variable bits.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>110xxxxx</strong>: 110xxxxx is the leading-bit pattern for Class C, not Class A.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>1110xxxx</strong>: 1110xxxx is the leading-bit pattern for Class D, not Class A.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>10xxxxxx</strong>: 10xxxxxx is the leading-bit pattern for Class B, not Class A.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The leading bits are the giveaway:</p><ul><li>0 = A.</li><li>10 = B.</li><li>110 = C.</li><li>1110 = D.</li><li>1111 = E.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1158';

-- Anki-NF-1159
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class B Binary Pattern</div><p>Each IPv4 (Internet Protocol version 4) address class has a leading-bit pattern in the first octet: Class A starts with 0 (0xxxxxxx), Class B starts with 10 (10xxxxxx), Class C starts with 110 (110xxxxx), Class D starts with 1110 (1110xxxx), and Class E starts with 1111 (1111xxxx).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>10xxxxxx</strong>: 10xxxxxx is correct because the first octet of a Class B address starts with the bits 10, followed by six variable bits.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>110xxxxx</strong>: 110xxxxx is the leading-bit pattern for Class C, not Class B.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>0xxxxxxx</strong>: 0xxxxxxx is the leading-bit pattern for Class A, not Class B.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>1110xxxx</strong>: 1110xxxx is the leading-bit pattern for Class D, not Class B.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The leading bits are the giveaway:</p><ul><li>0 = A.</li><li>10 = B.</li><li>110 = C.</li><li>1110 = D.</li><li>1111 = E.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1159';

-- Anki-NF-1160
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class C Binary Pattern</div><p>Each IPv4 (Internet Protocol version 4) address class has a leading-bit pattern in the first octet: Class A starts with 0 (0xxxxxxx), Class B starts with 10 (10xxxxxx), Class C starts with 110 (110xxxxx), Class D starts with 1110 (1110xxxx), and Class E starts with 1111 (1111xxxx).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>110xxxxx</strong>: 110xxxxx is correct because the first octet of a Class C address starts with the bits 110, followed by five variable bits.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>1110xxxx</strong>: 1110xxxx is the leading-bit pattern for Class D, not Class C.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>0xxxxxxx</strong>: 0xxxxxxx is the leading-bit pattern for Class A, not Class C.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>10xxxxxx</strong>: 10xxxxxx is the leading-bit pattern for Class B, not Class C.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The leading bits are the giveaway:</p><ul><li>0 = A.</li><li>10 = B.</li><li>110 = C.</li><li>1110 = D.</li><li>1111 = E.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1160';

-- Anki-NF-1161
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class D Binary Pattern</div><p>Each IPv4 (Internet Protocol version 4) address class has a leading-bit pattern in the first octet: Class A starts with 0 (0xxxxxxx), Class B starts with 10 (10xxxxxx), Class C starts with 110 (110xxxxx), Class D starts with 1110 (1110xxxx), and Class E starts with 1111 (1111xxxx).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>1110xxxx</strong>: 1110xxxx is correct because the first octet of a Class D address starts with the bits 1110, followed by four variable bits.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>1111xxxx</strong>: 1111xxxx is the leading-bit pattern for Class E, not Class D.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>110xxxxx</strong>: 110xxxxx is the leading-bit pattern for Class C, not Class D.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>10xxxxxx</strong>: 10xxxxxx is the leading-bit pattern for Class B, not Class D.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The leading bits are the giveaway:</p><ul><li>0 = A.</li><li>10 = B.</li><li>110 = C.</li><li>1110 = D.</li><li>1111 = E.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1161';

-- Anki-NF-1162
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class E Binary Pattern</div><p>Each IPv4 (Internet Protocol version 4) address class has a leading-bit pattern in the first octet: Class A starts with 0 (0xxxxxxx), Class B starts with 10 (10xxxxxx), Class C starts with 110 (110xxxxx), Class D starts with 1110 (1110xxxx), and Class E starts with 1111 (1111xxxx).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>1111xxxx</strong>: 1111xxxx is correct because the first octet of a Class E address starts with the bits 1111, followed by four variable bits.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>110xxxxx</strong>: 110xxxxx is the leading-bit pattern for Class C, not Class E.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>10xxxxxx</strong>: 10xxxxxx is the leading-bit pattern for Class B, not Class E.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>1110xxxx</strong>: 1110xxxx is the leading-bit pattern for Class D, not Class E.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The leading bits are the giveaway:</p><ul><li>0 = A.</li><li>10 = B.</li><li>110 = C.</li><li>1110 = D.</li><li>1111 = E.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1162';

-- Anki-NF-1171
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Subnet Masks - /8 Netmask</div><p>Each prefix length has a matching netmask: /8 = 255.0.0.0, /16 = 255.255.0.0, /24 = 255.255.255.0. The mask has 1s in the network portion and 0s in the host portion.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>255.0.0.0</strong>: 255.0.0.0 is correct because a /8 prefix length has eight 1 bits, which is the first octet set to 255 and the rest 0.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>255.255.255.0</strong>: 255.255.255.0 is the netmask for a /24 prefix length, not /8.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>255.255.255.255</strong>: 255.255.255.255 is a /32 host mask, not the netmask for /8.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>255.255.0.0</strong>: 255.255.0.0 is the netmask for a /16 prefix length, not /8.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Learn the three classful masks by heart:</p><ul><li>/8 = 255.0.0.0.</li><li>/16 = 255.255.0.0.</li><li>/24 = 255.255.255.0.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1171';

-- Anki-NF-1172
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Subnet Masks - /16 Netmask</div><p>Each prefix length has a matching netmask: /8 = 255.0.0.0, /16 = 255.255.0.0, /24 = 255.255.255.0. The mask has 1s in the network portion and 0s in the host portion.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>255.255.0.0</strong>: 255.255.0.0 is correct because a /16 prefix length has sixteen 1 bits, which is the first two octets set to 255 and the rest 0.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>255.0.0.0</strong>: 255.0.0.0 is the netmask for a /8 prefix length, not /16.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>255.255.255.255</strong>: 255.255.255.255 is a /32 host mask, not the netmask for /16.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>255.255.255.0</strong>: 255.255.255.0 is the netmask for a /24 prefix length, not /16.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Learn the three classful masks by heart:</p><ul><li>/8 = 255.0.0.0.</li><li>/16 = 255.255.0.0.</li><li>/24 = 255.255.255.0.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1172';

-- Anki-NF-1173
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Subnet Masks - /24 Netmask</div><p>Each prefix length has a matching netmask: /8 = 255.0.0.0, /16 = 255.255.0.0, /24 = 255.255.255.0. The mask has 1s in the network portion and 0s in the host portion.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>255.255.255.0</strong>: 255.255.255.0 is correct because a /24 prefix length has twenty-four 1 bits, which is the first three octets set to 255 and the last octet 0.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>255.0.0.0</strong>: 255.0.0.0 is the netmask for a /8 prefix length, not /24.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>255.255.255.255</strong>: 255.255.255.255 is a /32 host mask, not the netmask for /24.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>255.255.0.0</strong>: 255.255.0.0 is the netmask for a /16 prefix length, not /24.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Learn the three classful masks by heart:</p><ul><li>/8 = 255.0.0.0.</li><li>/16 = 255.255.0.0.</li><li>/24 = 255.255.255.0.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 07 Flashcards - IPv4 Addresses (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1173';

-- Anki-NF-1177
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class A Network Count</div><p>Class A has 7 network bits (the first octet minus the leading 0 bit), so it has 2^7 = 128 networks. Each Class A network has 24 host bits, giving over 16 million hosts per network.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Class A</strong>: Class A is correct because Class A has 2^7 = 128 networks.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Class C</strong>: Class C has 2^21 = 2,097,152 networks, not 128.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Class D</strong>: Class D is the multicast range; it is not divided into networks this way.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Class B</strong>: Class B has 2^14 = 16,384 networks, not 128.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Network counts:</p><ul><li>A = 128.</li><li>B = 16,384.</li><li>C = 2,097,152.</li></ul><p>They come from 2^(network bits).</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 08 Flashcards - IPv4 Addresses (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1177';

-- Anki-NF-1178
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class B Network Count</div><p>Class B has 14 network bits (the first two octets minus the leading 10 bits), so it has 2^14 = 16,384 networks. Each Class B network has 16 host bits, giving 65,534 usable hosts.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>Class B</strong>: Class B is correct because Class B has 2^14 = 16,384 networks.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Class D</strong>: Class D is the multicast range; it is not divided into networks this way.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Class C</strong>: Class C has 2^21 = 2,097,152 networks, not 16,384.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Class A</strong>: Class A has 2^7 = 128 networks, not 16,384.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Network counts:</p><ul><li>A = 128.</li><li>B = 16,384.</li><li>C = 2,097,152.</li></ul><p>They come from 2^(network bits).</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 08 Flashcards - IPv4 Addresses (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1178';

-- Anki-NF-1179
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class C Network Count</div><p>Class C has 21 network bits (the first three octets minus the leading 110 bits), so it has 2^21 = 2,097,152 networks. Each Class C network has 8 host bits, giving 254 usable hosts.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Class C</strong>: Class C is correct because Class C has 2^21 = 2,097,152 networks.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Class A</strong>: Class A has 2^7 = 128 networks, not 2,097,152.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Class D</strong>: Class D is the multicast range; it is not divided into networks this way.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Class B</strong>: Class B has 2^14 = 16,384 networks, not 2,097,152.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Network counts:</p><ul><li>A = 128.</li><li>B = 16,384.</li><li>C = 2,097,152.</li></ul><p>They come from 2^(network bits).</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 08 Flashcards - IPv4 Addresses (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1179';

-- Anki-NF-1180
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class A Host Count</div><p>Class A networks have 24 host bits, so each has 2^24 - 2 = 16,777,214 usable hosts (the -2 removes the network and broadcast addresses).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>Class A</strong>: Class A is correct because a Class A network allows 2^24 - 2 = 16,777,214 hosts.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Class B</strong>: A Class B network has 16 host bits, giving 65,534 hosts. Not 16,777,214.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Class C</strong>: A Class C network has 8 host bits, giving 254 hosts. Not 16,777,214.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Class D</strong>: Class D is the multicast range; it has no host count in this sense.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Host counts:</p><ul><li>A = 16,777,214.</li><li>B = 65,534.</li><li>C = 254.</li></ul><p>They come from (2^host bits) - 2.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 08 Flashcards - IPv4 Addresses (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1180';

-- Anki-NF-1181
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class B Host Count</div><p>Class B networks have 16 host bits, so each has 2^16 - 2 = 65,534 usable hosts (the -2 removes the network and broadcast addresses).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Class B</strong>: Class B is correct because a Class B network allows 2^16 - 2 = 65,534 hosts.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Class A</strong>: A Class A network has 24 host bits, giving 16,777,214 hosts. Not 65,534.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Class D</strong>: Class D is the multicast range; it has no host count in this sense.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Class C</strong>: A Class C network has 8 host bits, giving 254 hosts. Not 65,534.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Host counts:</p><ul><li>A = 16,777,214.</li><li>B = 65,534.</li><li>C = 254.</li></ul><p>They come from (2^host bits) - 2.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 08 Flashcards - IPv4 Addresses (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1181';

-- Anki-NF-1182
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Address Classes - Class C Host Count</div><p>Class C networks have 8 host bits, so each has 2^8 - 2 = 254 usable hosts (the -2 removes the network and broadcast addresses).</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>Class C</strong>: Class C is correct because a Class C network allows 2^8 - 2 = 254 hosts.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Class A</strong>: A Class A network has 24 host bits, giving 16,777,214 hosts. Not 254.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Class B</strong>: A Class B network has 16 host bits, giving 65,534 hosts. Not 254.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Class D</strong>: Class D is the multicast range; it has no host count in this sense.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Host counts:</p><ul><li>A = 16,777,214.</li><li>B = 65,534.</li><li>C = 254.</li></ul><p>They come from (2^host bits) - 2.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 08 Flashcards - IPv4 Addresses (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1182';

-- Anki-NF-1197
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Header: IHL Field Size</div><p>The IHL (Internet Header Length) field is only 4 bits long, which is why its maximum value is 15 (the largest number a 4-bit field can hold).</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>4</strong>: The IHL field is exactly 4 bits in length. Four bits can represent 0-15, which is why the maximum IHL value is 15.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>16</strong>: 16 bits is the size of the Total Length, Identification and Header Checksum fields, not IHL.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>32</strong>: 32 bits is the size of the Source and Destination IP (Internet Protocol) Address fields, not IHL.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>8</strong>: 8 bits is the size of the TTL (Time to Live) and Protocol fields, not IHL.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Link the field sizes together:</p><ul><li>IHL 4.</li><li>DSCP (Differentiated Services Code Point) 6.</li><li>ECN (Explicit Congestion Notification) 2.</li><li>Flags 3.</li><li>Fragment Offset 13.</li><li>Total Length / Identification / Checksum 16.</li><li>TTL / Protocol 8.</li><li>addresses 32.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📋 IPv4 Header - Full Reference (Memorize This):</div><table style=\"width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;\"><tr><td colspan=\"4\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Version<br><span style=\"font-size:12px;\">4 bits</span></td><td colspan=\"4\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">IHL<br><span style=\"font-size:12px;\">4 bits</span></td><td colspan=\"6\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">DSCP<br><span style=\"font-size:12px;\">6 bits</span></td><td colspan=\"2\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">ECN<br><span style=\"font-size:12px;\">2 bits</span></td><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Total Length<br><span style=\"font-size:12px;\">16 bits</span></td></tr><tr><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Identification<br><span style=\"font-size:12px;\">16 bits</span></td><td colspan=\"3\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Flags<br><span style=\"font-size:12px;\">3 bits</span></td><td colspan=\"13\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Fragment Offset<br><span style=\"font-size:12px;\">13 bits</span></td></tr><tr><td colspan=\"8\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">TTL<br><span style=\"font-size:12px;\">8 bits</span></td><td colspan=\"8\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Protocol<br><span style=\"font-size:12px;\">8 bits</span></td><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Header Checksum<br><span style=\"font-size:12px;\">16 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Source Address<br><span style=\"font-size:12px;\">32 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Destination Address<br><span style=\"font-size:12px;\">32 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Options + Padding<br><span style=\"font-size:12px;\">0-40 bytes</span></td></tr></table><div style=\"font-size:14px;line-height:1.7;margin-top:10px;\"><div style=\"margin-bottom:7px;\"><strong>Version</strong> <span style=\"opacity:0.75;\">(4 bits)</span>: IP version (4)</div><div style=\"margin-bottom:7px;\"><strong>IHL (Internet Header Length)</strong> <span style=\"opacity:0.75;\">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style=\"margin-bottom:7px;\"><strong>DSCP (Differentiated Services Code Point)</strong> <span style=\"opacity:0.75;\">(6 bits)</span>: QoS marking (0-63)</div><div style=\"margin-bottom:7px;\"><strong>ECN (Explicit Congestion Notification)</strong> <span style=\"opacity:0.75;\">(2 bits)</span>: Congestion notification (0-3)</div><div style=\"margin-bottom:7px;\"><strong>Total Length</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style=\"margin-bottom:7px;\"><strong>Identification</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Same ID for all fragments of one packet</div><div style=\"margin-bottom:7px;\"><strong>Flags</strong> <span style=\"opacity:0.75;\">(3 bits)</span>: Reserved (0), DF (Don\'t Fragment), MF (More Fragments)</div><div style=\"margin-bottom:7px;\"><strong>Fragment Offset</strong> <span style=\"opacity:0.75;\">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style=\"margin-bottom:7px;\"><strong>TTL (Time to Live)</strong> <span style=\"opacity:0.75;\">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style=\"margin-bottom:7px;\"><strong>Protocol</strong> <span style=\"opacity:0.75;\">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style=\"margin-bottom:7px;\"><strong>Header Checksum</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style=\"margin-bottom:7px;\"><strong>Source Address</strong> <span style=\"opacity:0.75;\">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style=\"margin-bottom:7px;\"><strong>Destination Address</strong> <span style=\"opacity:0.75;\">(32 bits)</span>: Receiver IPv4 address</div><div style=\"margin-bottom:7px;\"><strong>Options</strong> <span style=\"opacity:0.75;\">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style=\"margin-top:8px;\">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1197';

-- Anki-NF-1235
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Protocol Field: TCP</div><p>In the IPv4 (Internet Protocol version 4) Protocol field, the value 6 identifies TCP (Transmission Control Protocol). The receiving host reads this number and hands the payload to the TCP process.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>6</strong>: The Protocol field value 6 means TCP.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>1</strong>: Protocol value 1 means ICMP (Internet Control Message Protocol), not TCP.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>17</strong>: Protocol value 17 means UDP (User Datagram Protocol), not TCP.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>89</strong>: Protocol value 89 means OSPF (Open Shortest Path First), not TCP.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Protocol numbers to memorise:</p><ul><li>1 ICMP.</li><li>6 TCP.</li><li>17 UDP.</li><li>89 OSPF.</li></ul><p>The exam asks them in both directions.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📋 IPv4 Header - Full Reference (Memorize This):</div><table style=\"width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;\"><tr><td colspan=\"4\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Version<br><span style=\"font-size:12px;\">4 bits</span></td><td colspan=\"4\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">IHL<br><span style=\"font-size:12px;\">4 bits</span></td><td colspan=\"6\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">DSCP<br><span style=\"font-size:12px;\">6 bits</span></td><td colspan=\"2\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">ECN<br><span style=\"font-size:12px;\">2 bits</span></td><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Total Length<br><span style=\"font-size:12px;\">16 bits</span></td></tr><tr><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Identification<br><span style=\"font-size:12px;\">16 bits</span></td><td colspan=\"3\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Flags<br><span style=\"font-size:12px;\">3 bits</span></td><td colspan=\"13\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Fragment Offset<br><span style=\"font-size:12px;\">13 bits</span></td></tr><tr><td colspan=\"8\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">TTL<br><span style=\"font-size:12px;\">8 bits</span></td><td colspan=\"8\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Protocol<br><span style=\"font-size:12px;\">8 bits</span></td><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Header Checksum<br><span style=\"font-size:12px;\">16 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Source Address<br><span style=\"font-size:12px;\">32 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Destination Address<br><span style=\"font-size:12px;\">32 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Options + Padding<br><span style=\"font-size:12px;\">0-40 bytes</span></td></tr></table><div style=\"font-size:14px;line-height:1.7;margin-top:10px;\"><div style=\"margin-bottom:7px;\"><strong>Version</strong> <span style=\"opacity:0.75;\">(4 bits)</span>: IP version (4)</div><div style=\"margin-bottom:7px;\"><strong>IHL (Internet Header Length)</strong> <span style=\"opacity:0.75;\">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style=\"margin-bottom:7px;\"><strong>DSCP (Differentiated Services Code Point)</strong> <span style=\"opacity:0.75;\">(6 bits)</span>: QoS marking (0-63)</div><div style=\"margin-bottom:7px;\"><strong>ECN (Explicit Congestion Notification)</strong> <span style=\"opacity:0.75;\">(2 bits)</span>: Congestion notification (0-3)</div><div style=\"margin-bottom:7px;\"><strong>Total Length</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style=\"margin-bottom:7px;\"><strong>Identification</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Same ID for all fragments of one packet</div><div style=\"margin-bottom:7px;\"><strong>Flags</strong> <span style=\"opacity:0.75;\">(3 bits)</span>: Reserved (0), DF (Don\'t Fragment), MF (More Fragments)</div><div style=\"margin-bottom:7px;\"><strong>Fragment Offset</strong> <span style=\"opacity:0.75;\">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style=\"margin-bottom:7px;\"><strong>TTL (Time to Live)</strong> <span style=\"opacity:0.75;\">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style=\"margin-bottom:7px;\"><strong>Protocol</strong> <span style=\"opacity:0.75;\">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style=\"margin-bottom:7px;\"><strong>Header Checksum</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style=\"margin-bottom:7px;\"><strong>Source Address</strong> <span style=\"opacity:0.75;\">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style=\"margin-bottom:7px;\"><strong>Destination Address</strong> <span style=\"opacity:0.75;\">(32 bits)</span>: Receiver IPv4 address</div><div style=\"margin-bottom:7px;\"><strong>Options</strong> <span style=\"opacity:0.75;\">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style=\"margin-top:8px;\">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1235';

-- Anki-NF-1242
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Protocol Field: OSPF</div><p>In the IPv4 (Internet Protocol version 4) Protocol field, the value 89 identifies OSPF (Open Shortest Path First). Routers use this number to recognise OSPF packets.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>89</strong>: The Protocol field value 89 means OSPF.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>6</strong>: Protocol value 6 means TCP (Transmission Control Protocol), not OSPF.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>1</strong>: Protocol value 1 means ICMP (Internet Control Message Protocol), not OSPF.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>17</strong>: Protocol value 17 means UDP (User Datagram Protocol), not OSPF.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>89 = OSPF. Learn the full set together:</p><ul><li>1 ICMP.</li><li>6 TCP.</li><li>17 UDP.</li><li>89 OSPF.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📋 IPv4 Header - Full Reference (Memorize This):</div><table style=\"width:100%;border-collapse:collapse;margin-top:8px;font-size:13px;\"><tr><td colspan=\"4\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Version<br><span style=\"font-size:12px;\">4 bits</span></td><td colspan=\"4\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">IHL<br><span style=\"font-size:12px;\">4 bits</span></td><td colspan=\"6\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">DSCP<br><span style=\"font-size:12px;\">6 bits</span></td><td colspan=\"2\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">ECN<br><span style=\"font-size:12px;\">2 bits</span></td><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Total Length<br><span style=\"font-size:12px;\">16 bits</span></td></tr><tr><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Identification<br><span style=\"font-size:12px;\">16 bits</span></td><td colspan=\"3\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Flags<br><span style=\"font-size:12px;\">3 bits</span></td><td colspan=\"13\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Fragment Offset<br><span style=\"font-size:12px;\">13 bits</span></td></tr><tr><td colspan=\"8\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">TTL<br><span style=\"font-size:12px;\">8 bits</span></td><td colspan=\"8\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Protocol<br><span style=\"font-size:12px;\">8 bits</span></td><td colspan=\"16\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Header Checksum<br><span style=\"font-size:12px;\">16 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Source Address<br><span style=\"font-size:12px;\">32 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Destination Address<br><span style=\"font-size:12px;\">32 bits</span></td></tr><tr><td colspan=\"32\" style=\"border:1px solid #4a5568;padding:6px;text-align:center;\">Options + Padding<br><span style=\"font-size:12px;\">0-40 bytes</span></td></tr></table><div style=\"font-size:14px;line-height:1.7;margin-top:10px;\"><div style=\"margin-bottom:7px;\"><strong>Version</strong> <span style=\"opacity:0.75;\">(4 bits)</span>: IP version (4)</div><div style=\"margin-bottom:7px;\"><strong>IHL (Internet Header Length)</strong> <span style=\"opacity:0.75;\">(4 bits)</span>: Header length in 32-bit words (5-15); IHL × 4 = header bytes (20-60)</div><div style=\"margin-bottom:7px;\"><strong>DSCP (Differentiated Services Code Point)</strong> <span style=\"opacity:0.75;\">(6 bits)</span>: QoS marking (0-63)</div><div style=\"margin-bottom:7px;\"><strong>ECN (Explicit Congestion Notification)</strong> <span style=\"opacity:0.75;\">(2 bits)</span>: Congestion notification (0-3)</div><div style=\"margin-bottom:7px;\"><strong>Total Length</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Whole packet length in bytes, header + data (max 65,535)</div><div style=\"margin-bottom:7px;\"><strong>Identification</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Same ID for all fragments of one packet</div><div style=\"margin-bottom:7px;\"><strong>Flags</strong> <span style=\"opacity:0.75;\">(3 bits)</span>: Reserved (0), DF (Don\'t Fragment), MF (More Fragments)</div><div style=\"margin-bottom:7px;\"><strong>Fragment Offset</strong> <span style=\"opacity:0.75;\">(13 bits)</span>: Position of this fragment in the original packet (in 8-byte units)</div><div style=\"margin-bottom:7px;\"><strong>TTL (Time to Live)</strong> <span style=\"opacity:0.75;\">(8 bits)</span>: Max hops; each router subtracts 1, drops the packet at 0</div><div style=\"margin-bottom:7px;\"><strong>Protocol</strong> <span style=\"opacity:0.75;\">(8 bits)</span>: Next protocol: 1 = ICMP (Internet Control Message Protocol), 6 = TCP (Transmission Control Protocol), 17 = UDP (User Datagram Protocol), 89 = OSPF (Open Shortest Path First)</div><div style=\"margin-bottom:7px;\"><strong>Header Checksum</strong> <span style=\"opacity:0.75;\">(16 bits)</span>: Error check on the header only (recalculated at each hop)</div><div style=\"margin-bottom:7px;\"><strong>Source Address</strong> <span style=\"opacity:0.75;\">(32 bits)</span>: Sender IPv4 (Internet Protocol version 4) address</div><div style=\"margin-bottom:7px;\"><strong>Destination Address</strong> <span style=\"opacity:0.75;\">(32 bits)</span>: Receiver IPv4 address</div><div style=\"margin-bottom:7px;\"><strong>Options</strong> <span style=\"opacity:0.75;\">(0-40 bytes)</span>: Rarely used (e.g. Record Route, Timestamp); Padding pads the header to a multiple of 32 bits</div></div><p style=\"margin-top:8px;\">Total: 20 bytes minimum, up to 60 bytes with Options. IHL × 4 = header length in bytes.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 10 Flashcards - IPv4 Header)</div></div></div>' WHERE question_no = 'Anki-NF-1242';

-- Anki-NF-1254
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Subnet Masks: /25</div><p>A /25 prefix means the first 25 bits are network bits. The last octet has 1 network bit (128), so the mask is 255.255.255.128.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>255.255.255.128</strong>: The dotted decimal equivalent of a /25 prefix is 255.255.255.128.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>255.255.255.192</strong>: 255.255.255.192 is a /26 mask, not /25.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>255.255.255.224</strong>: 255.255.255.224 is a /27 mask, not /25.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>255.255.255.0</strong>: 255.255.255.0 is a /24 mask, not /25.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Learn the last-octet values in order:</p><ul><li>128 = /25.</li><li>192 = /26.</li><li>224 = /27.</li><li>240 = /28.</li><li>248 = /29.</li><li>252 = /30.</li><li>254 = /31.</li><li>255 = /32.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 13 Flashcards - Subnetting)</div></div></div>' WHERE question_no = 'Anki-NF-1254';

-- Anki-NF-1292
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Well-Known TCP Ports</div><p>HTTPS (Hypertext Transfer Protocol Secure) is the secure version of HTTP (Hypertext Transfer Protocol). It runs over TCP (Transmission Control Protocol) port 443, where TLS encrypts the web traffic before it is sent.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>443</strong>: HTTPS (HTTP Secure) is assigned TCP port 443 by IANA. Your browser connects to port 443 on a web server for encrypted web traffic.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>80</strong>: Port 80 is plain HTTP, the unencrypted version of web traffic, not HTTPS.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>23</strong>: Port 23 is Telnet, the old unencrypted remote-access protocol, not HTTPS.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>22</strong>: Port 22 is SSH (Secure Shell), used for secure remote command-line access to a device, not web browsing.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Remember the big three web/remote ports together:</p><ul><li>HTTP 80.</li><li>HTTPS 443.</li><li>SSH 22.</li><li>Telnet 23.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 30 Flashcards - TCP &amp; UDP)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1292';

-- Anki-NF-1337
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Regional Internet Registries - Africa</div><p>AFRINIC is the Regional Internet Registry (RIR) that controls IP (Internet Protocol) address assignments in Africa. Each RIR manages addresses for one part of the world.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>AFRINIC</strong>: AFRINIC serves Africa. Its name is built from AFRIca + NIC (Network Information Centre).</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>APNIC</strong>: APNIC serves the Asia-Pacific region, not Africa.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>ARIN</strong>: ARIN serves Canada, many Caribbean and North Atlantic islands, and the United States.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>RIPE NCC</strong>: RIPE NCC serves Europe, the Middle East and parts of Central Asia.</li></ul></div>\n  <div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>RIR names match their regions:</p><ul><li>AFRINIC = Africa.</li><li>APNIC = Asia-Pacific.</li><li>ARIN = America (North).</li><li>LACNIC = Latin America.</li><li>RIPE NCC = Europe.</li></ul></div>\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 31 Flashcards - IPv6 (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1337';

-- Anki-NF-1390
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv6 Well-Known Multicast Addresses</div><p>IPv6 has no broadcast.</p><p>Instead, devices use well-known link-local multicast addresses in the FF02 range.</p><p>Each address reaches one specific group.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>FF02::2</strong>: <strong>FF02::2</strong> is the well-known multicast address reserved for <strong>All routers</strong>.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>FF02::1</strong>: This address belongs to the <strong>All nodes</strong> group, not All routers.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>FF02::5</strong>: This address belongs to the <strong>All OSPF routers</strong> group, not All routers.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>FF02::9</strong>: This address belongs to the <strong>All RIP routers</strong> group, not All routers.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the FF02 series by the last digit:</p><ul><li>::1 all nodes.</li><li>::2 all routers.</li><li>::5 OSPF routers.</li><li>::6 OSPF DR/BDR.</li><li>::9 RIP.</li><li>::A EIGRP.</li></ul><p>The exam loves asking them both ways round.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1390';

-- Anki-NF-1392
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv6 Well-Known Multicast Addresses</div><p>IPv6 has no broadcast. Routers and hosts use well-known link-local multicast addresses in the FF02:: range, so one packet reaches a whole group at once. Each address is reserved for one specific group.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>FF02::5</strong>: FF02::5 is the well-known multicast address reserved for All OSPF routers.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>FF02::A</strong>: This address belongs to the All EIGRP routers group, not All OSPF routers.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>FF02::6</strong>: This address belongs to the All OSPF DRs/BDRs group, not All OSPF routers.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>FF02::2</strong>: This address belongs to the All routers group, not All OSPF routers.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the FF02:: series by the last digit:</p><ul><li>::1 all nodes.</li><li>::2 all routers.</li><li>::5 OSPF routers.</li><li>::6 OSPF DR/BDR.</li><li>::9 RIP.</li><li>::A EIGRP.</li></ul><p>The exam loves asking them both ways round.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div></div>' WHERE question_no = 'Anki-NF-1392';

-- Anki-NF-1394
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv6 Well-Known Multicast Addresses</div><p>IPv6 has no broadcast.</p><p>Instead, devices use well-known link-local multicast addresses in the FF02 range.</p><p>Each address reaches one specific group.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>FF02::6</strong>: <strong>FF02::6</strong> is the well-known multicast address reserved for <strong>All OSPF DRs/BDRs</strong>.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>FF02::2</strong>: This address belongs to the <strong>All routers</strong> group, not All OSPF DRs/BDRs.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>FF02::9</strong>: This address belongs to the <strong>All RIP routers</strong> group, not All OSPF DRs/BDRs.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>FF02::5</strong>: This address belongs to the <strong>All OSPF routers</strong> group, not All OSPF DRs/BDRs.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the FF02 series by the last digit:</p><ul><li>::1 all nodes.</li><li>::2 all routers.</li><li>::5 OSPF routers.</li><li>::6 OSPF DR/BDR.</li><li>::9 RIP.</li><li>::A EIGRP.</li></ul><p>The exam loves asking them both ways round.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1394';

-- Anki-NF-1396
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv6 Well-Known Multicast Addresses</div><p>IPv6 has no broadcast. Routers and hosts use well-known link-local multicast addresses in the FF02:: range, so one packet reaches a whole group at once. Each address is reserved for one specific group.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>FF02::9</strong>: FF02::9 is the well-known multicast address reserved for All RIP routers.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>FF02::2</strong>: This address belongs to the All routers group, not All RIP routers.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>FF02::5</strong>: This address belongs to the All OSPF routers group, not All RIP routers.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>FF02::A</strong>: This address belongs to the All EIGRP routers group, not All RIP routers.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the FF02:: series by the last digit:</p><ul><li>::1 all nodes.</li><li>::2 all routers.</li><li>::5 OSPF routers.</li><li>::6 OSPF DR/BDR.</li><li>::9 RIP.</li><li>::A EIGRP.</li></ul><p>The exam loves asking them both ways round.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div></div>' WHERE question_no = 'Anki-NF-1396';

-- Anki-NF-1398
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv6 Well-Known Multicast Addresses</div><p>IPv6 has no broadcast.</p><p>Instead, devices use well-known link-local multicast addresses in the FF02 range.</p><p>Each address reaches one specific group.</p></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>FF02::A</strong>: <strong>FF02::A</strong> is the well-known multicast address reserved for <strong>All EIGRP routers</strong>.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>FF02::9</strong>: This address belongs to the <strong>All RIP routers</strong> group, not All EIGRP routers.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>FF02::1</strong>: This address belongs to the <strong>All nodes</strong> group, not All EIGRP routers.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>FF02::6</strong>: This address belongs to the <strong>All OSPF DRs/BDRs</strong> group, not All EIGRP routers.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the FF02 series by the last digit:</p><ul><li>::1 all nodes.</li><li>::2 all routers.</li><li>::5 OSPF routers.</li><li>::6 OSPF DR/BDR.</li><li>::9 RIP.</li><li>::A EIGRP.</li></ul><p>The exam loves asking them both ways round.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1398';

-- Anki-NF-1400
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Well-Known Multicast Addresses</div><p>IPv4 multicast uses 224.0.0.0/24 for link-local multicast. Routing protocols each listen on their own well-known address, so a router can send one packet to every router running the same protocol on the link.</p><p>The IPv4 and IPv6 versions use the same last digit. EIGRP is FF02::A in IPv6, and hex A is decimal 10.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>224.0.0.10</strong>: 224.0.0.10 is the well-known multicast address reserved for All EIGRP routers.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>224.0.0.5</strong>: This address belongs to the All OSPF routers group, not All EIGRP routers.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>224.0.0.9</strong>: This address belongs to the All RIP routers group, not All EIGRP routers.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>224.0.0.6</strong>: This address belongs to the All OSPF DRs/BDRs group, not All EIGRP routers.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Learn the 224.0.0.x set together:</p><ul><li>.1 all nodes.</li><li>.2 all routers.</li><li>.5 OSPF.</li><li>.6 OSPF DR/BDR.</li><li>.9 RIP.</li><li>.10 EIGRP.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div></div>' WHERE question_no = 'Anki-NF-1400';

-- Anki-NF-1402
