-- Anki-NF-1411
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv4 Well-Known Multicast Addresses</div><p>IPv4 multicast uses 224.0.0.0/24 for link-local multicast. Each routing protocol listens on its own well-known address, so one packet reaches every router running that protocol on the link.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>All nodes</strong>: 224.0.0.1 is the well-known multicast address for all nodes.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>All EIGRP routers</strong>: That is 224.0.0.10, not 224.0.0.1.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>All routers</strong>: That is 224.0.0.2, not 224.0.0.1.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>All OSPF routers</strong>: That is 224.0.0.5, not 224.0.0.1.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Learn the 224.0.0.x set together:</p><ul><li>.1 all nodes.</li><li>.2 all routers.</li><li>.5 OSPF.</li><li>.6 OSPF DR/BDR.</li><li>.9 RIP.</li><li>.10 EIGRP.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div></div>' WHERE question_no = 'Anki-NF-1411';

-- Anki-NF-1440
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: NDP Message Types</div><p>Each NDP message is an ICMPv6 packet with a fixed type number. Do not mix up NS/NA (for MAC addresses) with RS/RA (for finding routers).</p><ul><li>133 = RS, Router Solicitation</li><li>134 = RA, Router Advertisement</li><li>135 = NS, Neighbor Solicitation</li><li>136 = NA, Neighbor Advertisement</li></ul></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>NS</strong>: NS (Neighbor Solicitation) is ICMPv6 Type 135.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>NA</strong>: NA (Neighbor Advertisement) is Type 136, the reply to an NS.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>RS</strong>: RS (Router Solicitation) is Type 133, used to find a router.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>RA</strong>: RA (Router Advertisement) is Type 134, sent by a router.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>NDP types in order:</p><ul><li>133 RS.</li><li>134 RA.</li><li>135 NS.</li><li>136 NA.</li></ul><p>Remember 133-134 routers, 135-136 neighbours.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div></div>' WHERE question_no = 'Anki-NF-1440';

-- Anki-NF-1441
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: NDP Message Types</div><p>NDP messages are ICMPv6 packets, and each one has a fixed type number:</p><ul><li>133 RS, Router Solicitation.</li><li>134 RA, Router Advertisement.</li><li>135 NS, Neighbor Solicitation.</li><li>136 NA, Neighbor Advertisement.</li></ul></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>135</strong>: NS, Neighbor Solicitation, is ICMPv6 type 135. It is the NDP version of an ARP request: Hi, what is your MAC address?</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>133</strong>: 133 is Router Solicitation, RS, not Neighbor Solicitation.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>134</strong>: 134 is Router Advertisement, RA, not Neighbor Solicitation.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>136</strong>: 136 is Neighbor Advertisement, NA, not Neighbor Solicitation.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>NDP types in order:</p><ul><li>133 RS.</li><li>134 RA.</li><li>135 NS.</li><li>136 NA.</li></ul><p>Remember: 133-134 are routers, 135-136 are neighbours.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1441';

-- Anki-NF-1442
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: NDP Message Types</div><p>Each NDP message is an ICMPv6 packet with its own type number.</p><ul><li>133 = RS, Router Solicitation.</li><li>134 = RA, Router Advertisement.</li><li>135 = NS, Neighbor Solicitation.</li><li>136 = NA, Neighbor Advertisement.</li></ul></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>NA</strong>: NA, Neighbor Advertisement, is ICMPv6 Type 136.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>RS</strong>: RS is Type 133. It is the host asking for a router, not a Neighbor Advertisement.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>RA</strong>: RA is Type 134. It is the router announcing itself, not a Neighbor Advertisement.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>NS</strong>: NS is Type 135. It asks for a MAC address, not a Neighbor Advertisement.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>NDP types in order:</p><ul><li>133 RS.</li><li>134 RA.</li><li>135 NS.</li><li>136 NA.</li></ul><p>Remember 133 and 134 are about routers, 135 and 136 are about neighbours.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1442';

-- Anki-NF-1443
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: NDP Message Types</div><p>Each NDP message is an ICMPv6 packet with a fixed type number.</p><ul><li>133 = RS, Router Solicitation. 134 = RA, Router Advertisement.</li><li>135 = NS, Neighbor Solicitation. 136 = NA, Neighbor Advertisement.</li></ul></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>136</strong>: NA, Neighbor Advertisement, is ICMPv6 Type 136. It sends the MAC address back to the requester, as unicast.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>135</strong>: 135 is NS, Neighbor Solicitation, the NDP version of an ARP request.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>133</strong>: 133 is RS, Router Solicitation, a host asking if any routers are on the link.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>134</strong>: 134 is RA, Router Advertisement, a router announcing itself and the network prefix.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>NDP types in order:</p><ul><li>133 RS.</li><li>134 RA.</li><li>135 NS.</li><li>136 NA.</li></ul><p>Remember \"133-134 routers, 135-136 neighbours\".</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div></div>' WHERE question_no = 'Anki-NF-1443';

-- Anki-NF-1444
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: NDP Message Types</div><p>Each NDP message is an ICMPv6 packet with a fixed type number. Do not mix up NS/NA (for MAC addresses) with RS/RA (for finding routers).</p><ul><li>133 = RS, Router Solicitation</li><li>134 = RA, Router Advertisement</li><li>135 = NS, Neighbor Solicitation</li><li>136 = NA, Neighbor Advertisement</li></ul></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>RS</strong>: RS (Router Solicitation) is ICMPv6 Type 133. A host sends it to FF02::2 (all routers) to ask: are there any routers on this link?</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>NS</strong>: NS (Neighbor Solicitation) is Type 135, used to learn a MAC address.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>NA</strong>: NA (Neighbor Advertisement) is Type 136, the reply to an NS.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>RA</strong>: RA (Router Advertisement) is Type 134, sent by a router.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>NDP types in order:</p><ul><li>133 RS.</li><li>134 RA.</li><li>135 NS.</li><li>136 NA.</li></ul><p>Remember 133-134 routers, 135-136 neighbours.</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div></div>' WHERE question_no = 'Anki-NF-1444';

-- Anki-NF-1445
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: NDP Message Types</div><p>NDP messages are ICMPv6 packets, and each one has a fixed type number:</p><ul><li>133 RS, Router Solicitation.</li><li>134 RA, Router Advertisement.</li><li>135 NS, Neighbor Solicitation.</li><li>136 NA, Neighbor Advertisement.</li></ul></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>133</strong>: RS, Router Solicitation, is ICMPv6 type 133. A host sends it to FF02::2, all routers, to ask if any router is on the link.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>135</strong>: 135 is Neighbor Solicitation, NS, not Router Solicitation.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>134</strong>: 134 is Router Advertisement, RA, not Router Solicitation.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>136</strong>: 136 is Neighbor Advertisement, NA, not Router Solicitation.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>NDP types in order:</p><ul><li>133 RS.</li><li>134 RA.</li><li>135 NS.</li><li>136 NA.</li></ul><p>Remember: 133-134 are routers, 135-136 are neighbours.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1445';

-- Anki-NF-1446
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: NDP Message Types</div><p>Each NDP message is an ICMPv6 packet with its own type number.</p><ul><li>133 = RS, Router Solicitation.</li><li>134 = RA, Router Advertisement.</li><li>135 = NS, Neighbor Solicitation.</li><li>136 = NA, Neighbor Advertisement.</li></ul></div>\n  <div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>RA</strong>: RA, Router Advertisement, is ICMPv6 Type 134.</li></ul></div>\n  <div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>NA</strong>: NA is Type 136. It is the reply that gives a MAC address, not a Router Advertisement.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>NS</strong>: NS is Type 135. It asks for a MAC address, not a Router Advertisement.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>RS</strong>: RS is Type 133. It is the host asking for a router, not a Router Advertisement.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>NDP types in order:</p><ul><li>133 RS.</li><li>134 RA.</li><li>135 NS.</li><li>136 NA.</li></ul><p>Remember 133 and 134 are about routers, 135 and 136 are about neighbours.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1446';

-- Anki-NF-1447
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: NDP Message Types</div><p>Each NDP message is an ICMPv6 packet with a fixed type number.</p><ul><li>133 = RS, Router Solicitation. 134 = RA, Router Advertisement.</li><li>135 = NS, Neighbor Solicitation. 136 = NA, Neighbor Advertisement.</li></ul></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>134</strong>: RA, Router Advertisement, is ICMPv6 Type 134. It is sent by a router to all nodes, to announce the network prefix.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>133</strong>: 133 is RS, Router Solicitation, a host asking if any routers are on the link.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>136</strong>: 136 is NA, Neighbor Advertisement, the reply that sends a MAC address back.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>135</strong>: 135 is NS, Neighbor Solicitation, the NDP version of an ARP request.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>NDP types in order:</p><ul><li>133 RS.</li><li>134 RA.</li><li>135 NS.</li><li>136 NA.</li></ul><p>Remember \"133-134 routers, 135-136 neighbours\".</p></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div></div>' WHERE question_no = 'Anki-NF-1447';

-- Anki-NF-1461
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv6 Static Routes</div><p>A static route is made with ipv6 route, then the destination and prefix length, then the exit interface, the next hop, or both. The three forms are:</p><ul><li>Directly attached: exit interface only.</li><li>Recursive: next hop only.</li><li>Fully specified: both.</li></ul></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>directly attached</strong>: Directly attached means only the exit interface is given. That is the form described here.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>recursive</strong>: Recursive gives only the next hop address.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>floating</strong>: Floating is not a route form. It is a backup route with a higher administrative distance. It is only used if the main route goes away.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>fully specified</strong>: Fully specified gives both the exit interface and the next hop.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Static route forms:</p><ul><li>directly attached = exit interface only.</li><li>recursive = next hop only.</li><li>fully specified = both.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1461';

-- Anki-NF-1464
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: IPv6 Static Routes</div><p>There are three kinds of static route, the same for IPv4 and IPv6:</p><ul><li>Directly attached: only the exit interface is given</li><li>Recursive: only the next-hop address is given</li><li>Fully specified: BOTH the exit interface and the next hop are given</li></ul></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>fully specified</strong>: The fully specified form is the one described here. Both the exit interface and the next hop are given in the command.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>directly attached</strong>: Directly attached means exit interface only, with no next hop.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>recursive</strong>: Recursive means next hop only, with no exit interface.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>floating</strong>: A floating static route is a backup route with a higher administrative distance. It is not a form defined by what is specified in the command.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Static route forms:</p><ul><li>directly attached = exit interface only.</li><li>recursive = next hop only.</li><li>fully specified = both.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 33 Flashcards - IPv6 (Part 3)</div></div></div>' WHERE question_no = 'Anki-NF-1464';

-- Anki-NF-1544
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cloud Computing (NIST)</div><p>NIST defines five essential characteristics of cloud computing: on-demand self-service, broad network access, resource pooling, rapid elasticity and measured service. Measured service means usage is metered and the customer is billed for what is used.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>Measured service</strong>: The fifth of the five essential characteristics is Measured service: cloud usage is measured and reported, so the customer pays for what is used.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>Metered service</strong>: Metered describes the same idea, but the exact NIST term is Measured service.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Monitored service</strong>: Monitored describes watching the service, but the exact NIST term is Measured service.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Usage-based billing</strong>: Usage-based billing is the result of measured service, but it is not the NIST term.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>The five:</p><ul><li>on-demand self-service.</li><li>broad network access.</li><li>resource pooling.</li><li>rapid elasticity.</li><li>measured service.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 54 (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1544';

-- Anki-NF-1556
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Cloud Deployment Models (NIST)</div><p>NIST defines four cloud deployment models: private cloud, community cloud, public cloud and hybrid cloud.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>Private cloud</strong>: The four deployment models are private, community, public and hybrid, so the missing first model is Private cloud.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Protected cloud</strong>: Protected cloud is not one of the four NIST deployment models.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Personal cloud</strong>: Personal cloud is not one of the four NIST deployment models.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Partner cloud</strong>: Partner cloud is not one of the four NIST deployment models.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Four deployment models:</p><ul><li>private.</li><li>community.</li><li>public.</li><li>hybrid.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 54 (Part 1)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1556';

-- Anki-SEC-5040
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: AAA</div><p>AAA (Authentication, Authorization, and Accounting) stands for Authentication, Authorization, and Accounting, the three functions that control and record access to a network: who you are, what you may do, and what you did.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option B</span> <strong>Authentication, Authorization, and Accounting</strong>: AAA stands for Authentication, Authorization, and Accounting.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option C</span> <strong>Authentication, Access, and Auditing</strong>: Authentication, Access, and Auditing is not the expansion, the correct second and third words are Authorization and Accounting.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Authorization, Authentication, and Accounting</strong>: Authorization, Authentication, and Accounting has the first two words in the wrong order, the correct order is Authentication, Authorization, and Accounting.</li><li><span class=\"opt-tag wrong\">Option A</span> <strong>Authentication, Authorization, and Administration</strong>: Authentication, Authorization, and Administration is not the expansion, the third word is Accounting, not Administration.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>AAA order matters:</p><ul><li>first prove who you are (Authentication).</li><li>then get your permissions (Authorization).</li><li>then log what you did (Accounting).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 48 Flashcards - Security Fundamentals)</div></div></div>' WHERE question_no = 'Anki-SEC-5040';

-- Anki-SEC-5059
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Port Security</div><p>The port security violation mode is configured with switchport port-security violation followed by shutdown, restrict or protect, which decides what happens when an unauthorised MAC (Media Access Control) address appears.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>switchport port-security violation { shutdown | restrict | protect }</strong>: The command switchport port-security violation { shutdown | restrict | protect } configures the violation mode.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option D</span> <strong>switchport port-security aging type { absolute | inactivity }</strong>: switchport port-security aging type configures how secure addresses age out, not what happens on a violation.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>switchport port-security maximum 1</strong>: switchport port-security maximum 1 sets the number of allowed secure addresses, not the violation mode.</li><li><span class=\"opt-tag wrong\">Option A</span> <strong>switchport port-security mac-address sticky</strong>: switchport port-security mac-address sticky enables sticky learning, it does not set the violation mode.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Violation modes:</p><ul><li>shutdown (default, err-disables the port).</li><li>restrict (drops and logs).</li><li>protect (drops silently).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 49 Flashcards - Port Security)</div></div></div>' WHERE question_no = 'Anki-SEC-5059';

-- Anki-SEC-5111
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Dynamic ARP Inspection - errdisable Recovery</div><p>When DAI (Dynamic ARP Inspection) rate limiting is exceeded, the port is err-disabled. To let it recover automatically, enable errdisable recovery for the arp-inspection cause with errdisable recovery cause arp-inspection.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option D</span> <strong>errdisable recovery cause arp-inspection</strong>: errdisable recovery cause arp-inspection is the command that enables automatic recovery for ports err-disabled by DAI rate limiting.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>brute force</strong>: Brute force is a password attack type, not an errdisable recovery cause.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>show ip dhcp snooping binding</strong>: This is a show command that displays the binding table; it does not enable errdisable recovery.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>82</strong>: Option 82 is the DHCP (Dynamic Host Configuration Protocol) relay agent information option; it has nothing to do with DAI errdisable recovery.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Match the cause to the feature:</p><ul><li>arp-inspection for DAI.</li><li>dhcp-rate-limit for DHCP snooping.</li><li>psecure-violation for port security.</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 51 Flashcards - Dynamic ARP Inspection)</div></div></div>' WHERE question_no = 'Anki-SEC-5111';

-- Anki-SEC-5117
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\"><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Dynamic ARP Inspection - Applying an ARP ACL</div><p>After creating an ARP (Address Resolution Protocol) ACL (Access Control List), it is applied to DAI (Dynamic ARP Inspection) for a VLAN (Virtual Local Area Network) with ip arp inspection filter arp-acl-name vlan vlan. DAI then accepts ARP messages that match the ACL, even if they are not in the DHCP (Dynamic Host Configuration Protocol) snooping binding table.</p></div><div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>ip arp inspection filter arp-acl-name vlan vlan</strong>: ip arp inspection filter arp-acl-name vlan vlan is the command that applies an ARP ACL to DAI.</li></ul></div><div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option B</span> <strong>ip arp inspection trust</strong>: This marks an interface trusted for DAI; it does not apply an ARP ACL.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>ip arp inspection filter vlan vlan</strong>: This is incomplete; the filter command needs the ARP ACL name before the vlan keyword.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>ip arp inspection vlan vlan</strong>: This enables DAI on a VLAN, but it does not apply an ARP ACL to it.</li></ul></div><div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Three steps for ARP ACLs:</p><ul><li>create it (arp access-list).</li><li>add entries (permit ip host ... mac host ...).</li><li>apply it (ip arp inspection filter ... vlan ...).</li></ul></div><div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Security Fundamentals (CCNA / Day 51 Flashcards - Dynamic ARP Inspection)</div></div></div>' WHERE question_no = 'Anki-SEC-5117';

-- Drag & Drop #2
UPDATE questions SET explanation = '\n<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\">\n    <div class=\"section-title-concept\">📌 Core Concept: IPv4 Subnetting & Prefix Lengths from Routing Table</div>\n    <p>In the exhibit routing table (<code>show ip route</code>), each subnet entry indicates its specific prefix length (CIDR notation). To match each network to its dotted-decimal subnet mask, convert the slash notation to its 32-bit subnet mask equivalent:</p>\n    <ul>\n      <li><code>/25</code> = 25 ones = 11111111.11111111.11111111.10000000 = <code>255.255.255.128</code></li>\n      <li><code>/28</code> = 28 ones = 11111111.11111111.11111111.11110000 = <code>255.255.255.240</code></li>\n      <li><code>/29</code> = 29 ones = 11111111.11111111.11111111.11111000 = <code>255.255.255.248</code></li>\n      <li><code>/30</code> = 30 ones = 11111111.11111111.11111111.11111100 = <code>255.255.255.252</code></li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card correct-card\">\n    <h4 class=\"section-title-correct\">✓ Correct Matching & Solution:</h4>\n    <ul>\n      <li><strong>10.10.13.0:</strong> <code>255.255.255.128</code> (Exhibit shows: <code>10.10.13.0/25 [110/2] via 10.10.10.1</code>)</li>\n      <li><strong>10.10.13.128:</strong> <code>255.255.255.240</code> (Exhibit shows: <code>10.10.13.128/28 [110/2] via 10.10.10.1</code>)</li>\n      <li><strong>10.10.13.160:</strong> <code>255.255.255.248</code> (Exhibit shows: <code>10.10.13.160/29 [110/2] via 10.10.10.1</code>)</li>\n      <li><strong>10.10.13.252:</strong> <code>255.255.255.252</code> (Exhibit shows: <code>10.10.13.252/30 [110/2] via 10.10.10.1</code>)</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card why-card\" style=\"background: rgba(30, 41, 59, 0.7); border: 1px solid rgba(148, 163, 184, 0.2); border-left: 4px solid #818cf8; border-radius: 0.75rem; padding: 1.1rem 1.3rem; margin-top: 10px;\">\n    <h4 style=\"color: #a5b4fc; margin-bottom: 0.6rem; font-size: 1.25rem;\">🔍 Analysis of Unused Distractors:</h4>\n    <ul>\n      <li><code>255.255.248.0</code>: An unused distractor mask representing 2048 IP addresses. No /21 routes exist in the exhibit.</li>\n      <li><code>255.255.255.224</code>: While the exhibit contains external subnets like 209.165.200.0/27, the target column specifically asks for the 10.10.13.x subnets.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card tip-card\">\n    <div class=\"section-title-tip\">💡 CCNA Exam Tip: Powers of Two Subnetting</div>\n    <p>Remember the last octet magic values:</p><ul><li>/25 = 128 (128 IPs).</li><li>/26 = 192 (64 IPs).</li><li>/27 = 224 (32 IPs).</li><li>/28 = 240 (16 IPs).</li><li>/29 = 248 (8 IPs).</li><li>/30 = 252 (4 IPs).</li><li>/31 = 254 (2 IPs).</li><li>/32 = 255 (host route).</li></ul>\n  </div>\n</div>\n' WHERE question_no = 'Drag & Drop #2';

-- Question #103
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\">\n    <div class=\"section-title-concept\">📌 Core Concept: Cisco IOS SSH Configuration Requirements</div>\n    <p>Configuring secure administrative access via SSH on Cisco devices requires only a specific set of foundational commands. Auxiliary services are unnecessary for SSH operations.</p>\n  </div>\n\n  <div class=\"expl-card correct-card\">\n    <h4 class=\"section-title-correct\">✓ Why the Correct Answers (Options C & D) are Correct:</h4>\n    <ul>\n      <li><span class=\"opt-tag correct\">Option C</span> <code>no ip name-server 198.51.100.210</code>: An external DNS name server is not required for generating RSA keys or operating an SSH server on Cisco IOS.</li>\n      <li><span class=\"opt-tag correct\">Option D</span> <code>no service password-encryption</code>: Enabling weak Type 7 password encryption is an optional convenience; it has no role in SSH cryptographic key negotiation or transport. Removing it cleans the unnecessary configuration.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card incorrect-card\">\n    <h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4>\n    <ul>\n      <li><span class=\"opt-tag wrong\">Option A</span>: <code>login local</code> on the VTY lines is strictly mandatory for SSH user credential authentication. Removing it breaks SSH logins.</li>\n      <li><span class=\"opt-tag wrong\">Option B</span>: <code>ip domain-name</code> is required to construct the device Fully Qualified Domain Name (FQDN) used during RSA key generation.</li>\n      <li><span class=\"opt-tag wrong\">Option E</span>: <code>hostname</code> is mandatory; Cisco IOS refuses to generate RSA keys with the default factory hostname \"Router\" or \"Switch\".</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card tip-card\">\n    <h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4>\n    <p>Mandatory SSH Steps:</p><ul><li>(1) <code>hostname &lt;name&gt;</code>.</li><li>(2) <code>ip domain-name &lt;domain&gt;</code>.</li><li>(3) <code>crypto key generate rsa</code>.</li><li>(4) <code>username &lt;user&gt; secret &lt;pass&gt;</code>.</li><li>(5) <code>line vty 0 4</code> -> <code>login local</code> + <code>transport input ssh</code>.</li></ul>\n  </div>\n</div>' WHERE question_no = 'Question #103';

-- Question #117
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\">\n    <div class=\"section-title-concept\">📌 Core Concept: Next-Generation Firewall (NGFW) Functions</div>\n    <p>Enterprise firewalls deliver multi-layered network perimeter defense, combining stateful traffic inspection, VPN gateway termination, and Layer 7 application filtering.</p>\n  </div>\n\n  <div class=\"expl-card correct-card\">\n    <h4 class=\"section-title-correct\">✓ Why the Correct Answers (Options A & D) are Correct:</h4>\n    <ul>\n      <li><span class=\"opt-tag correct\">Option A</span> <strong>Serves as an endpoint for a site-to-site VPN</strong>: Firewalls act as IPsec/SSL VPN gateways, establishing encrypted tunnels between headquarters, data centers, and branch offices.</li>\n      <li><span class=\"opt-tag correct\">Option D</span> <strong>Enables traffic filtering based on URLs</strong>: Next-Generation Firewalls inspect Layer 7 HTTP/HTTPS traffic to filter and block malicious or non-compliant web URLs and categories.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card incorrect-card\">\n    <h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4>\n    <ul>\n      <li><span class=\"opt-tag wrong\">Option B</span>: Domain name resolution is the responsibility of DNS servers, not firewalls.</li>\n      <li><span class=\"opt-tag wrong\">Option C</span>: Providing wireless connectivity is performed by Access Points (APs) and WLCs.</li>\n      <li><span class=\"opt-tag wrong\">Option E</span>: Layer 2 switching between local LAN hosts is performed by Ethernet switches.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card tip-card\">\n    <h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4>\n    <p>Core Firewall Capabilities:</p><ul><li>Stateful packet filtering.</li><li>NAT translation.</li><li>VPN tunnel termination.</li><li>Layer 7 Deep Packet / URL Inspection.</li></ul>\n  </div>\n</div>' WHERE question_no = 'Question #117';

-- Question #13
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\">\n    <div class=\"section-title-concept\">📌 Core Concept: Cisco Lightweight AP Operational Modes</div>\n    <p>Cisco Access Points can operate in multiple specialized modes depending on whether they serve client traffic, act as sensors, or extend wired network segments.</p>\n  </div>\n\n  <div class=\"expl-card correct-card\">\n    <h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option B) is Correct:</h4>\n    <ul>\n      <li><span class=\"opt-tag correct\">Option B</span> <strong>bridge</strong>: In Bridge mode (Mesh), the AP acts as a dedicated wireless bridge (Point-to-Point or Point-to-Multipoint) connecting two or more distant wired network segments across buildings or campus locations without laying physical cables.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card incorrect-card\">\n    <h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4>\n    <ul>\n      <li><span class=\"opt-tag wrong\">Option A</span> <strong>local</strong>: Default mode where the AP broadcasts BSSIDs, handles wireless client association, and tunnels all client data via CAPWAP to the WLC.</li>\n      <li><span class=\"opt-tag wrong\">Option C</span> <strong>root</strong>: Autonomous AP operating role, not a standard controller-based AP mode for bridging buildings.</li>\n      <li><span class=\"opt-tag wrong\">Option D</span> <strong>FlexConnect</strong>: Designed for branch deployments, allowing local switching of client traffic while maintaining centralized control plane management.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card tip-card\">\n    <h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4>\n    <p>AP Modes:</p><ul><li><strong>Local</strong> (regular client access).</li><li><strong>FlexConnect</strong> (branch local switching).</li><li><strong>Bridge</strong> (wireless bridging between segments).</li><li><strong>Sniffer</strong> (packet capture).</li><li><strong>Monitor</strong> (location & rogue detection).</li></ul>\n  </div>\n</div>' WHERE question_no = 'Question #13';

-- Question #144
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\">\n    <div class=\"section-title-concept\">📌 Core Concept: JSON Syntax & Object Data Structures</div>\n    <p>JSON (JavaScript Object Notation) organizes structured data into key-value pairs formatted as <code>\"key\": value</code>.</p>\n  </div>\n\n  <div class=\"expl-card correct-card\">\n    <h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C - key) is Correct:</h4>\n    <ul>\n      <li><span class=\"opt-tag correct\">Option C</span> <strong>key</strong>: In JSON objects enclosed in curly braces <code>{ \"apple\": \"fruit\" }</code>, the identifier preceding the colon is the <strong>key</strong> (name attribute), while the item following the colon is the value.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card incorrect-card\">\n    <h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4>\n    <ul>\n      <li><span class=\"opt-tag wrong\">Option A</span> <strong>string</strong>: While keys are textual strings, its structural role in the key-value architecture is a <strong>key</strong>.</li>\n      <li><span class=\"opt-tag wrong\">Option B</span> <strong>object</strong>: An object is the entire collection of key-value pairs wrapped in <code>{ ... }</code>.</li>\n      <li><span class=\"opt-tag wrong\">Option D</span> <strong>number</strong>: Numbers are unquoted numeric literals (e.g. <code>25</code> or <code>10.5</code>).</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card tip-card\">\n    <h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4>\n    <p>JSON Anatomy:</p><ul><li><code>{ }</code> = Object.</li><li><code>[ ]</code> = Array.</li><li><code>\"property\":</code> = <strong>Key</strong>.</li><li><code>\"value\"</code> = String Value.</li></ul>\n  </div>\n</div>' WHERE question_no = 'Question #144';

-- Question #6
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\">\n    <div class=\"section-title-concept\">📌 Core Concept: Cisco IOS Secure Shell (SSHv2) Requirements</div>\n    <p>To establish secure SSHv2 administrative access on a Cisco router, several foundational cryptographic and system parameters must be configured in sequence.</p>\n  </div>\n\n  <div class=\"expl-card correct-card\">\n    <h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option D) is Correct:</h4>\n    <ul>\n      <li><span class=\"opt-tag correct\">Option D</span>:\n        <ul>\n          <li><code>hostname R15</code>: Must change default name \'Router\' before generating RSA keys.</li>\n          <li><code>ip domain-name cisco.com</code>: Required to formulate the router\'s Fully Qualified Domain Name (FQDN) for the RSA key pair.</li>\n          <li><code>crypto key generate rsa general-keys modulus 1024</code>: Generates the RSA key pair (modulus &ge; 768 bits is required for SSHv2; 1024 or higher recommended).</li>\n          <li><code>ip ssh version 2</code>: Enforces SSH version 2.</li>\n          <li><code>line vty 0 15</code> &rarr; <code>transport input ssh</code>: Disables insecure Telnet and restricts incoming management sessions to SSH.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card incorrect-card\">\n    <h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4>\n    <ul>\n      <li><span class=\"opt-tag wrong\">Option A</span>: Lacks <code>hostname</code> and <code>ip domain-name</code>, which causes key generation to fail with error <em>\"% Please define a domain-name first\"</em>.</li>\n      <li><span class=\"opt-tag wrong\">Option B</span>: Uses <code>transport input all</code> (allowing unencrypted Telnet) and fails to set a unique hostname.</li>\n      <li><span class=\"opt-tag wrong\">Option C</span>: Omits <code>ip domain-name</code> and <code>ip ssh version 2</code>.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card tip-card\">\n    <h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4>\n    <p>SSH Prerequisites Mnemonic:</p><ul><li><strong>Host</strong>.</li><li><strong>Domain</strong>.</li><li><strong>Crypto</strong>.</li><li><strong>VTY</strong>.</li></ul>\n  </div>\n</div>' WHERE question_no = 'Question #6';

-- Question #73
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n  <div class=\"expl-card concept-card\">\n    <div class=\"section-title-concept\">📌 Core Concept: Dynamic Host Configuration Protocol (DHCP, RFC 2131)</div>\n    <p>DHCP automates network layer configuration, dynamically providing IP addresses, subnet masks, default gateways, and DNS servers to client workstations.</p>\n  </div>\n\n  <div class=\"expl-card correct-card\">\n    <h4 class=\"section-title-correct\">✓ Why the Correct Answers (Options B and C) are Correct:</h4>\n    <ul>\n      <li><span class=\"opt-tag correct\">Option B</span> <strong>to control the length of time an IP address is used by a network device</strong>: DHCP implements a <strong>lease duration</strong> timer, allowing addresses to be automatically reclaimed when devices leave the network and reallocated to new devices.</li>\n      <li><span class=\"opt-tag correct\">Option C</span> <strong>to reduce administrative time in managing IP address ranges for clients</strong>: Centrally managing address scopes eliminates the manual burden and errors associated with manually assigning static IP configurations on every individual end-user workstation.</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card incorrect-card\">\n    <h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4>\n    <ul>\n      <li><span class=\"opt-tag wrong\">Option A</span>: Accessing websites by name instead of IP is the purpose of <strong>DNS</strong>, not DHCP.</li>\n      <li><span class=\"opt-tag wrong\">Option D</span>: Manually configuring addresses is static IP configuration, which DHCP specifically replaces.</li>\n      <li><span class=\"opt-tag wrong\">Option E</span>: Selecting the best path to reach an IP address is the role of <strong>routing protocols</strong> (OSPF/EIGRP/BGP).</li>\n    </ul>\n  </div>\n\n  <div class=\"expl-card tip-card\">\n    <h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4>\n    <p>DHCP Benefits:</p><ul><li><strong>Saves Admin Time</strong>.</li><li>prevents IP conflicts.</li><li>enables <strong>IP Lease Management</strong> & automatic address reclamation.</li></ul>\n  </div>\n</div>' WHERE question_no = 'Question #73';

